module.exports = [{"name": "Kode.gs", "code": "/**\n * ============================================================\n *  AIUEO CAFE — backend (Netlify Function + Supabase)\n * ============================================================\n *  Kode ini ditulis sinkron (warisan Apps Script) dan dijalankan oleh server/runtime.js.\n *  Penyimpanan: PostgreSQL di Supabase (tiap nama di HEADERS = satu tabel, semua kolom teks, kolom rn = nomor baris).\n *  Pengaturan rahasia lewat variabel lingkungan Netlify: SUPABASE_URL, SUPABASE_SERVICE_KEY, ADMIN_PHONE, FONNTE_TOKEN, DEBUG_OTP.\n */\n\nconst COUNTRY_CODE = '62';   // Indonesia\nconst QR_TTL = 120;\nconst DEFAULT_TYPE = 'default';  // id event stamp (campaign) bawaan. Kolom stamp_type di Rewards/Stamps/Redemptions = id campaign.          // detik, masa berlaku QR dinamis pelanggan\n\n/* ===================== SKEMA DATA ===================== */\nconst HEADERS = {\n  // Kolom baru HARUS selalu ditambah di belakang agar data lama tidak bergeser.\n  Users:       ['user_id','phone','name','email','role','member_code','stamps','total_earned','total_redeemed','active','created_at','last_login','last_stamp_at','claimed_ids',\n                'username','username_key','gender','vp_total','vp_month','vp_month_key','grp_change_key','grp_change_ts','auto_created'],\n  Stamps:      ['id','user_id','customer_name','qty','type','by_user','by_name','note','ts','stamp_type','card_id','void_of'],\n  AdminLog:    ['id','ts','by_user','by_name','action','detail'],\n  Backups:     ['id','ts','table_name','n_rows','csv'],\n  Redemptions: ['id','user_id','customer_name','reward_name','stamps_used','by_user','by_name','ts','reward_id','stamp_type','card_id'],\n  Rewards:     ['id','name','description','stamps_required','stamp_type','active','sort','created_at'],\n  Campaigns:   ['id','name','description','icon','start','end','redeem_until','active','sort','created_at'],\n  Cards:       ['card_id','user_id','campaign_id','stamps','claimed_ids','status','created_at','completed_at'],\n  Events:      ['id','title','subtitle','badge','image_url','link','start','end','active','sort','created_at'],\n  Sessions:    ['token_hash','user_id','expires','remember','device','created_at'],\n  Settings:    ['key','value','description'],\n  Games:       ['id','name','image_url','min_players','max_players','level','duration','mechanics','description','active','play_count','last_played','created_at'],\n  Tiers:       ['id','name','min_vp','benefit','color','active','sort','created_at'],\n  PointsLedger:['id','user_id','username','amount','source','ref','note','by_user','by_name','ts'],\n  Groups:      ['id','name','leader_id','status','first_done','waiting_since','created_at','rename_key','rename_ts'],\n  GroupMembers:['id','group_id','user_id','kid_id','status','invited_by','joined_at','left_at'],\n  Kids:        ['id','name','guardian_id','active','created_at'],\n  Visits:      ['id','date','ts','user_id','kid_id','type','hours','group_id','by_user','by_name','stamp','vp'],\n  VisitGames:  ['id','game_id','game_name','players','group_id','by_user','by_name','ts'],\n  Activities:  ['id','kind','title','description','start','vp','gm_id','status','active','created_at'],\n  ActReg:      ['id','activity_id','user_id','status','placement','ts'],\n  Badges:      ['id','code','name','icon','description','metric','threshold','active','sort'],\n  UserBadges:  ['id','user_id','code','ts'],\n  Feed:        ['id','ts','kind','username','text'],\n  Notifications:['id','user_id','kind','title','body','ts','read','ref','by_name'],\n  NotifRules:  ['id','code','name','enabled','days','title','body','last_run'],\n  GroupRenames:['id','group_id','requester_id','old_name','new_name','status','note','ts','decided_by','decided_at'],\n  PushSubs:    ['id','user_id','endpoint','p256dh','auth','ts','ua']\n};\n\n// Pengaturan yang bisa diubah admin dari web app. t: s=teks, text=teks panjang, n=angka, c=warna\nconst SETTING_DEFS = {\n  cafe_name:            {t:'s',    d:'AIUEO Cafe',                          label:'Nama kafe', max:60},\n  tagline:              {t:'s',    d:'Main bareng, kumpulkan stamp & VP',    label:'Tagline', max:120},\n  theme_color:          {t:'c',    d:'#16A34A',                            label:'Warna tema'},\n  reward_terms:         {t:'text', d:'Berlaku untuk semua menu minuman.',  label:'Syarat & ketentuan reward (tampil di kartu)', max:300},\n  max_qty_per_add:      {t:'n',    d:3,  min:1,  max:20,                   label:'Maks. stamp sekali input'},\n  cooldown_minutes:     {t:'n',    d:5,  min:0,  max:360,                  label:'Jeda antar stamp per pelanggan per event (menit, 0 = tanpa jeda)'},\n  max_open_cards:       {t:'n',    d:3,  min:1,  max:10,                   label:'Maks. kartu belum selesai per pelanggan per event'},\n  otp_ttl_minutes:      {t:'n',    d:5,  min:2,  max:15,                   label:'Masa berlaku OTP (menit)'},\n  session_days_remember:{t:'n',    d:30, min:1,  max:365,                  label:'Lama \"Ingat saya\" (hari)'},\n  session_hours_default:{t:'n',    d:12, min:1,  max:72,                   label:'Lama sesi tanpa \"Ingat saya\" (jam)'},\n  // VP (Victory Points) dari bermain. Nilai awal 0 = belum memberi VP; isi sesuai kebijakan kafe.\n  party_cooldown_days:  {t:'n',    d:0,  min:0,  max:365,                  label:'Jeda perubahan Party (hari). 0 = reset otomatis tiap tanggal 1'},\n  vp_play_reguler:      {t:'n',    d:0,  min:0,  max:100000,                label:'VP per kunjungan - main Reguler'},\n  vp_play_party:        {t:'n',    d:0,  min:0,  max:100000,                label:'VP per kunjungan - main Party'},\n  vp_play_allday:       {t:'n',    d:0,  min:0,  max:100000,                label:'VP per kunjungan - All-Day Pass'},\n  vp_top1:              {t:'n',    d:0,  min:0,  max:100000,                label:'VP tambahan turnamen - Juara 1'},\n  vp_top2:              {t:'n',    d:0,  min:0,  max:100000,                label:'VP tambahan turnamen - Juara 2'},\n  vp_top3:              {t:'n',    d:0,  min:0,  max:100000,                label:'VP tambahan turnamen - Juara 3'},\n  vp_hour_reguler:      {t:'n',    d:0,  min:0,  max:100000,                label:'VP tambahan per jam - main Reguler'},\n  vp_hour_party:        {t:'n',    d:0,  min:0,  max:100000,                label:'VP tambahan per jam - main Party'}\n};\n\n/* ===================== SETUP (otomatis sekali; aman diulang) ===================== */\nconst SETUP_VERSION = '2';\nlet _setupOk = false;\n\nfunction ensureSetup_() {\n  if (_setupOk) return;\n  if (prop_('SETUP_V') !== SETUP_VERSION) {\n    withLock_(function () { if (prop_('SETUP_V') !== SETUP_VERSION) setup(); });\n  }\n  _setupOk = true;\n}\n\nfunction setup() {\n  const props = PropertiesService.getScriptProperties();\n  if (!findOne_('Rewards', 'stamp_type', DEFAULT_TYPE)) {   // contoh milestone awal, bebas diubah di menu Admin\n    appendObj_('Rewards', {id: newId_('RWD'), name: 'Gratis 1 cookies', description: 'Pilih cookies favorit', stamps_required: 5, stamp_type: DEFAULT_TYPE, active: 'Y', sort: 1, created_at: nowStr_()});\n    appendObj_('Rewards', {id: newId_('RWD'), name: 'Gratis 1 minuman', description: 'Semua menu minuman', stamps_required: 10, stamp_type: DEFAULT_TYPE, active: 'Y', sort: 2, created_at: nowStr_()});\n  }\n  if (!findOne_('Campaigns', 'id', DEFAULT_TYPE)) {\n    appendObj_('Campaigns', {id: DEFAULT_TYPE, name: 'Kartu Reguler', description: 'Berlaku sepanjang waktu', icon: '☕', start: '', end: '', redeem_until: '', active: 'Y', sort: 0, created_at: nowStr_()});\n  }\n  const have = {};\n  readAll_('Settings').forEach(function (r) { have[r.key] = 1; });\n  Object.keys(SETTING_DEFS).forEach(function (k) {\n    if (!have[k]) appendObj_('Settings', {key: k, value: SETTING_DEFS[k].d, description: SETTING_DEFS[k].label});\n  });\n  seedTiers_();\n  seedBadges_();\n  seedNotifRules_();\n  if (!props.getProperty('HMAC_SECRET')) props.setProperty('HMAC_SECRET', Utilities.getUuid() + Utilities.getUuid());\n  props.setProperty('SETUP_V', SETUP_VERSION);\n}\n\n/** Dijalankan harian (Netlify scheduled function): hapus sesi kedaluwarsa dan sisa cache/ping lama. */\nfunction dailyCleanup() {\n  __DB.remove('sessions', JSON.stringify([['expires', 'lt', String(Date.now())]]));\n  __DB.purge();\n  try { if (fmt_(new Date(), 'u') === '1') makeBackup_(); } catch (e) { console.error('Backup mingguan gagal: ' + (e && e.message)); }   // Senin\n}\n\nconst ALL = ['customer', 'cashier', 'gm', 'admin'], STAFF = ['cashier', 'admin'], ADMIN = ['admin'], CUST = ['customer'], FLOOR = ['cashier', 'gm', 'admin'];\n\n// Rute modul baru ada di Katalog.gs. Dibungkus fungsi agar urutan file di editor Apps Script tidak berpengaruh.\nconst ROUTES = {\n  username_check: {fn: function (p, u, t) { return r_usernameCheck_(p, u, t); }},\n  profile_complete:{roles: ALL, fn: function (p, u, t) { return r_profileComplete_(p, u, t); }},\n  games_list:     {roles: ALL,   fn: function (p, u, t) { return r_gamesList_(p, u, t); }},\n  games_admin:    {roles: ADMIN, fn: function (p, u, t) { return r_gamesAdmin_(p, u, t); }},\n  game_save:      {roles: ADMIN, fn: function (p, u, t) { return r_gameSave_(p, u, t); }},\n  game_delete:    {roles: ADMIN, fn: function (p, u, t) { return r_gameDelete_(p, u, t); }},\n  tiers_list:     {roles: ADMIN, fn: function (p, u, t) { return r_tiersList_(p, u, t); }},\n  tier_save:      {roles: ADMIN, fn: function (p, u, t) { return r_tierSave_(p, u, t); }},\n  tier_delete:    {roles: ADMIN, fn: function (p, u, t) { return r_tierDelete_(p, u, t); }},\n  vp_adjust:      {roles: ADMIN, fn: function (p, u, t) { return r_vpAdjust_(p, u, t); }},\n  leaderboard:    {roles: ALL,   fn: function (p, u, t) { return r_leaderboard_(p, u, t); }},\n  group_my:       {roles: CUST,  fn: function (p, u, t) { return r_groupMy_(p, u, t); }},\n  group_create:   {roles: CUST,  fn: function (p, u, t) { return r_groupCreate_(p, u, t); }},\n  group_invite:   {roles: CUST,  fn: function (p, u, t) { return r_groupInvite_(p, u, t); }},\n  group_respond:  {roles: CUST,  fn: function (p, u, t) { return r_groupRespond_(p, u, t); }},\n  group_leave:    {roles: CUST,  fn: function (p, u, t) { return r_groupLeave_(p, u, t); }},\n  group_rename_request:{roles: CUST, fn: function (p, u, t) { return r_groupRenameRequest_(p, u, t); }},\n  group_rename_cancel: {roles: CUST, fn: function (p, u, t) { return r_groupRenameCancel_(p, u, t); }},\n  renames_list:   {roles: ADMIN, fn: function (p, u, t) { return r_renamesList_(p, u, t); }},\n  rename_decide:  {roles: ADMIN, fn: function (p, u, t) { return r_renameDecide_(p, u, t); }},\n  group_kid_add:  {roles: CUST,  fn: function (p, u, t) { return r_groupKidAdd_(p, u, t); }},\n  group_kid_remove:{roles: CUST, fn: function (p, u, t) { return r_groupKidRemove_(p, u, t); }},\n  groups_find:    {roles: STAFF, fn: function (p, u, t) { return r_groupsFind_(p, u, t); }},\n  group_staff_view:{roles: STAFF, fn: function (p, u, t) { return r_groupStaffView_(p, u, t); }},\n  visit_meta:     {roles: FLOOR, fn: function (p, u, t) { return r_visitMeta_(p, u, t); }},\n  visit_party:    {roles: STAFF, fn: function (p, u, t) { return r_visitParty_(p, u, t); }},\n  visit_single:   {roles: STAFF, fn: function (p, u, t) { return r_visitSingle_(p, u, t); }},\n  visit_batch:    {roles: STAFF, fn: function (p, u, t) { return r_visitBatch_(p, u, t); }},\n  game_play:      {roles: FLOOR, fn: function (p, u, t) { return r_gamePlay_(p, u, t); }},\n  push_key:       {roles: ALL,   fn: function (p, u, t) { return r_pushKey_(p, u, t); }},\n  push_subscribe: {roles: ALL,   fn: function (p, u, t) { return r_pushSubscribe_(p, u, t); }},\n  push_unsubscribe:{roles: ALL,  fn: function (p, u, t) { return r_pushUnsubscribe_(p, u, t); }},\n  push_config_get:{roles: ADMIN, fn: function (p, u, t) { return r_pushConfigGet_(p, u, t); }},\n  push_config_save:{roles: ADMIN, fn: function (p, u, t) { return r_pushConfigSave_(p, u, t); }},\n  push_test:      {roles: ADMIN, fn: function (p, u, t) { return r_pushTest_(p, u, t); }},\n  notif_list:     {roles: ALL,   fn: function (p, u, t) { return r_notifList_(p, u, t); }},\n  notif_read:     {roles: ALL,   fn: function (p, u, t) { return r_notifRead_(p, u, t); }},\n  notif_send:     {roles: ADMIN, fn: function (p, u, t) { return r_notifSend_(p, u, t); }},\n  notif_rules:    {roles: ADMIN, fn: function (p, u, t) { return r_notifRules_(p, u, t); }},\n  notif_rule_save:{roles: ADMIN, fn: function (p, u, t) { return r_notifRuleSave_(p, u, t); }},\n  notif_run_auto: {roles: ADMIN, fn: function (p, u, t) { return r_notifRunAuto_(p, u, t); }},\n  feed:           {roles: ALL,   fn: function (p, u, t) { return r_feed_(p, u, t); }},\n  my_collection:  {roles: CUST,  fn: function (p, u, t) { return r_myCollection_(p, u, t); }},\n  my_badges:      {roles: CUST,  fn: function (p, u, t) { return r_myBadges_(p, u, t); }},\n  badges_admin:   {roles: ADMIN, fn: function (p, u, t) { return r_badgesAdmin_(p, u, t); }},\n  badge_save:     {roles: ADMIN, fn: function (p, u, t) { return r_badgeSave_(p, u, t); }},\n  acts_list:      {roles: ALL,   fn: function (p, u, t) { return r_actsList_(p, u, t); }},\n  act_register:   {roles: CUST,  fn: function (p, u, t) { return r_actRegister_(p, u, t); }},\n  acts_admin:     {roles: ADMIN, fn: function (p, u, t) { return r_actsAdmin_(p, u, t); }},\n  act_save:       {roles: ADMIN, fn: function (p, u, t) { return r_actSave_(p, u, t); }},\n  act_delete:     {roles: ADMIN, fn: function (p, u, t) { return r_actDelete_(p, u, t); }},\n  acts_mine:      {roles: FLOOR, fn: function (p, u, t) { return r_actsMine_(p, u, t); }},\n  act_roster:     {roles: FLOOR, fn: function (p, u, t) { return r_actRoster_(p, u, t); }},\n  act_attend:     {roles: FLOOR, fn: function (p, u, t) { return r_actAttend_(p, u, t); }},\n  act_result:     {roles: FLOOR, fn: function (p, u, t) { return r_actResult_(p, u, t); }},\n  public_info:    {fn: r_publicInfo_},\n  otp_request:    {fn: r_otpRequest_},\n  otp_verify:     {fn: r_otpVerify_},\n  bootstrap:      {roles: ALL,   fn: r_bootstrap_},\n  poll:           {light: true,  fn: r_poll_},\n  my_qr:          {roles: ALL,   fn: r_myQr_},\n  my_history:     {roles: ALL,   fn: r_myHistory_},\n  profile_update: {roles: ALL,   fn: r_profileUpdate_},\n  logout:         {roles: ALL,   fn: r_logout_},\n  logout_all:     {roles: ALL,   fn: r_logoutAll_},\n  cust_lookup:    {roles: STAFF, fn: r_custLookup_},\n  stamp_add:      {roles: STAFF, fn: r_stampAdd_},\n  reward_redeem:  {roles: STAFF, fn: r_rewardRedeem_},\n  stamp_batch:    {roles: STAFF, fn: r_stampBatch_},\n  redeem_batch:   {roles: STAFF, fn: r_redeemBatch_},\n  campaigns_list: {roles: ADMIN, fn: r_campaignsList_},\n  campaign_save:  {roles: ADMIN, fn: r_campaignSave_},\n  campaign_delete:{roles: ADMIN, fn: r_campaignDelete_},\n  rewards_list:   {roles: ADMIN, fn: r_rewardsList_},\n  reward_save:    {roles: ADMIN, fn: r_rewardSave_},\n  reward_delete:  {roles: ADMIN, fn: r_rewardDelete_},\n  staff_activity: {roles: STAFF, fn: r_staffActivity_},\n  stamp_adjust:   {roles: ADMIN, fn: r_stampAdjust_},\n  events_list:    {roles: ADMIN, fn: r_eventsList_},\n  event_save:     {roles: ADMIN, fn: r_eventSave_},\n  event_delete:   {roles: ADMIN, fn: r_eventDelete_},\n  settings_get:   {roles: ADMIN, fn: r_settingsGet_},\n  settings_save:  {roles: ADMIN, fn: r_settingsSave_},\n  stats:          {roles: ADMIN, fn: r_stats_},\n  user_search:    {roles: ADMIN, fn: r_userSearch_},\n  party_quota_list: {roles: ADMIN, fn: function (p, u, t) { return r_partyQuotaList_(p, u, t); }},\n  party_quota_reset:{roles: ADMIN, fn: function (p, u, t) { return r_partyQuotaReset_(p, u, t); }},\n  export_csv:     {roles: ADMIN, fn: function (p, u, t) { return r_exportCsv_(p, u, t); }},\n  export_tables:  {roles: ADMIN, fn: function (p, u, t) { return r_exportTables_(p, u, t); }},\n  admin_log:      {roles: ADMIN, fn: function (p, u, t) { return r_adminLog_(p, u, t); }},\n  entry_void:     {roles: ADMIN, fn: function (p, u, t) { return r_entryVoid_(p, u, t); }},\n  cust_suggest:   {roles: STAFF, fn: function (p, u, t) { return r_custSuggest_(p, u, t); }},\n  backups_list:   {roles: ADMIN, fn: function (p, u, t) { return r_backupsList_(p, u, t); }},\n  backup_make:    {roles: ADMIN, fn: function (p, u, t) { return r_backupMake_(p, u, t); }},\n  backup_get:     {roles: ADMIN, fn: function (p, u, t) { return r_backupGet_(p, u, t); }},\n  user_update:    {roles: ADMIN, fn: r_userUpdate_}\n};\n\n/** Satu-satunya pintu API yang dipanggil dari browser (lewat /api). */\nconst AUDIT_ = {vp_adjust: 1, stamp_adjust: 1, settings_save: 1, user_update: 1, rename_decide: 1, entry_void: 1, party_quota_reset: 1, notif_send: 1,\n  tier_delete: 1, tier_save: 1, reward_save: 1, reward_delete: 1, campaign_save: 1, campaign_delete: 1, game_save: 1, act_delete: 1, backup_make: 1};\nfunction logAdmin_(who, action, payload) {\n  let d = '';\n  try { const o = {}; Object.keys(payload || {}).forEach(function (k) { if (k !== 'image' && k !== 'token') o[k] = payload[k]; }); d = JSON.stringify(o).slice(0, 300); } catch (e) {}\n  appendObj_('AdminLog', {id: newId_('LOG'), ts: nowStr_(), by_user: who.user_id, by_name: who.username || who.name || '', action: action, detail: d});\n}\nfunction api(action, token, payload) {\n  try {\n    ensureSetup_();\n    const route = ROUTES[action];\n    if (!route) throw appErr_('Aksi tidak dikenal');\n    if (route.light) return {ok: true, data: route.fn(payload || {}, authLight_(token), token)};\n    let user = null;\n    if (route.roles) {\n      user = authenticate_(token);\n      if (route.roles.indexOf(user.role) < 0) throw appErr_('Anda tidak punya akses', 'FORBIDDEN');\n    }\n    const data = route.fn(payload || {}, user, token);\n    if (user && AUDIT_[action]) { try { logAdmin_(user, action, payload); } catch (e2) { /* log tidak boleh menggagalkan aksi */ } }\n    return {ok: true, data: data};\n  } catch (e) {\n    if (!e.code) console.error(e && e.stack || e);\n    return {ok: false, error: e.code ? e.message : 'Terjadi kesalahan di server. Coba lagi.', code: e.code || 'ERR'};\n  }\n}\n\n/* ===================== AUTH: OTP + SESSION ===================== */\nfunction r_publicInfo_() {\n  const s = settings_();\n  return {\n    cafe_name: s.cafe_name, tagline: s.tagline, theme_color: s.theme_color,\n    session_days_remember: s.session_days_remember,\n    channels: {whatsapp: waEnabled_()}\n  };\n}\n\nfunction r_otpRequest_(p) {\n  const phone = normPhone_(p.phone);\n  if (!waEnabled_()) throw appErr_('Pengiriman kode WhatsApp belum diaktifkan. Hubungi kasir/admin.');\n  rateLimit_('OTPREQ_' + phone, 5, 900);\n\n  const s = settings_();\n  const u = userByPhone_(phone);\n  if (u && u.active === 'N') throw appErr_('Akun ini dinonaktifkan. Hubungi kasir/admin.');\n\n  // Nomor baru wajib mengisi Nama lengkap, Username (unik), dan Gender sebelum kode dikirim.\n  let info = {name: '', username: '', gender: ''};\n  if (!u) {\n    const name = clean_(p.name, 60);\n    if (!name || !p.username || !p.gender) return {needInfo: true};\n    const un = normUsername_(p.username);\n    if (usernameTaken_(un.key)) throw appErr_('Username sudah dipakai. Pilih yang lain.', 'USERNAME_TAKEN');\n    info = {name: name, username: un.name, gender: normGender_(p.gender)};\n  }\n\n  const code = genOtp_();\n  const ttl = s.otp_ttl_minutes;\n  const entry = {h: otpHash_(phone, code), exp: Date.now() + ttl * 60000, attempts: 0, name: info.name, username: info.username, gender: info.gender, email: '', channel: 'whatsapp'};\n  CacheService.getScriptCache().put('OTP_' + phone, JSON.stringify(entry), ttl * 60);\n\n  sendWhatsApp_(phone, 'Kode login ' + s.cafe_name + ': ' + code + '. Berlaku ' + ttl + ' menit. Jangan bagikan kode ini kepada siapa pun.');\n  return {sent: true, channel: 'whatsapp', ttl: ttl, to: maskPhone_(phone)};\n}\n\nfunction r_otpVerify_(p) {\n  const phone = normPhone_(p.phone);\n  const code = String(p.code || '').replace(/\\D/g, '');\n  const cache = CacheService.getScriptCache();\n  const raw = cache.get('OTP_' + phone);\n  if (!raw) throw appErr_('Kode kedaluwarsa. Minta kode baru.');\n  const e = JSON.parse(raw);\n  if (e.attempts >= 5) { cache.remove('OTP_' + phone); throw appErr_('Terlalu banyak percobaan. Minta kode baru.'); }\n  if (code.length !== 6 || e.h !== otpHash_(phone, code)) {\n    e.attempts++;\n    cache.put('OTP_' + phone, JSON.stringify(e), Math.max(1, Math.round((e.exp - Date.now()) / 1000)));\n    throw appErr_('Kode salah. Sisa percobaan: ' + (5 - e.attempts));\n  }\n  cache.remove('OTP_' + phone);\n\n  const s = settings_();\n  return withLock_(function () {\n    let u = userByPhone_(phone);\n    if (!u) {\n      // dicek ulang di dalam lock: dua orang yang mendaftar bersamaan tidak boleh mendapat username yang sama\n      if (e.username && usernameTaken_(String(e.username).toLowerCase())) {\n        throw appErr_('Username \"' + e.username + '\" baru saja dipakai orang lain. Daftar ulang dengan username lain.', 'USERNAME_TAKEN');\n      }\n      u = createUser_(phone, e.name || 'Pelanggan', e.email, {username: e.username, gender: e.gender});\n    }\n    if (u.active === 'N') throw appErr_('Akun ini dinonaktifkan.');\n    const patch = {last_login: nowStr_()};\n    if (phone === adminPhone_() && u.role !== 'admin') patch.role = 'admin';\n    updateRow_('Users', u._row, patch);\n    Object.assign(u, patch);\n\n    const remember = !!p.remember;\n    const ms = remember ? s.session_days_remember * 86400000 : s.session_hours_default * 3600000;\n    const token = (Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, '');\n    appendObj_('Sessions', {\n      token_hash: sha256_(token), user_id: u.user_id, expires: Date.now() + ms,\n      remember: remember ? 'Y' : 'N', device: clean_(p.device, 80), created_at: nowStr_()\n    });\n    return {token: token, expires: Date.now() + ms, user: pubUser_(u)};\n  });\n}\n\n/** Cek sesi ringan (dari cache 60 detik) untuk polling; jatuh ke authenticate_ bila cache kosong. */\nfunction authLight_(token) {\n  if (!token) throw appErr_('Silakan masuk terlebih dahulu', 'AUTH');\n  const hit = CacheService.getScriptCache().get('SES_' + sha256_(String(token)));\n  if (hit) { const o = JSON.parse(hit); if (o.exp > Date.now()) return {user_id: o.uid}; }\n  return {user_id: authenticate_(token).user_id};\n}\n\nfunction authenticate_(token) {\n  if (!token) throw appErr_('Silakan masuk terlebih dahulu', 'AUTH');\n  const s = findOne_('Sessions', 'token_hash', sha256_(String(token)));\n  if (!s || Number(s.expires) < Date.now()) {\n    if (s) delRow_('Sessions', s._row);\n    throw appErr_('Sesi berakhir, silakan masuk lagi', 'AUTH');\n  }\n  const u = findOne_('Users', 'user_id', s.user_id);\n  if (!u || u.active === 'N') throw appErr_('Akun tidak aktif', 'AUTH');\n  CacheService.getScriptCache().put('SES_' + sha256_(String(token)), JSON.stringify({uid: s.user_id, exp: Number(s.expires)}), 60);\n\n  // \"Ingat saya\" bergulir: perpanjang bila sisa < 7 hari\n  if (s.remember === 'Y' && Number(s.expires) - Date.now() < 7 * 86400000) {\n    updateRow_('Sessions', s._row, {expires: Date.now() + settings_().session_days_remember * 86400000});\n  }\n  return u;\n}\n\nfunction r_logout_(p, u, token) {\n  CacheService.getScriptCache().remove('SES_' + sha256_(String(token)));\n  const s = findOne_('Sessions', 'token_hash', sha256_(String(token)));\n  if (s) delRow_('Sessions', s._row);\n  return {};\n}\nfunction r_logoutAll_(p, u) { deleteWhere_('Sessions', 'user_id', u.user_id); return {}; }\n\n/* ===================== CUSTOMER ===================== */\nfunction r_bootstrap_(p, u) {\n  const s = settings_();\n  return {user: pubUser_(u), view: custView_(u), settings: pubSettings_(s), events: activeEvents_(), version: ver_(u.user_id), topic: pingTopic_(u.user_id),\n    pingUrl: prop_('SUPABASE_ANON_KEY') ? String(prop_('SUPABASE_URL') || '').replace(/\\/+$/, '') : '', pingKey: prop_('SUPABASE_ANON_KEY') || ''};\n}\n\n/** Polling ringan: browser kirim versi terakhir; data baru dikirim hanya jika ada perubahan (stamp/tukar/koreksi). */\nfunction r_poll_(p, light) {\n  const v = ver_(light.user_id);\n  if (String(p.v || '') === v) return {changed: false, v: v};\n  const u = userById_(light.user_id);\n  if (!u || u.active === 'N') throw appErr_('Akun tidak aktif', 'AUTH');\n  return {changed: true, v: v, view: custView_(u)};\n}\n\nfunction r_myQr_(p, u) {\n  const ts = Math.floor(Date.now() / 1000);\n  return {payload: 'LS1.' + u.member_code + '.' + ts + '.' + qrSig_(u.member_code, ts), ttl: QR_TTL, code: u.member_code};\n}\n\nfunction r_myHistory_(p, u) {\n  const names = campNames_(), items = [];\n  tail_('Stamps', 3000).forEach(function (r) {\n    if (r.user_id === u.user_id) items.push({kind: r.type, qty: Number(r.qty), note: r.note, ts: r.ts, campaign: names[r.stamp_type || DEFAULT_TYPE] || ''});\n  });\n  tail_('Redemptions', 1000).forEach(function (r) {\n    if (r.user_id === u.user_id) items.push({kind: 'redeem', qty: Number(r.stamps_used), note: r.reward_name, ts: r.ts, campaign: names[r.stamp_type || DEFAULT_TYPE] || ''});\n  });\n  tail_('PointsLedger', 1000).forEach(function (r) {\n    if (r.user_id === u.user_id) items.push({kind: 'vp', qty: Number(r.amount), note: r.note || vpSourceLabel_(r.source), ts: r.ts, campaign: ''});\n  });\n  items.sort(function (a, b) { return a.ts < b.ts ? 1 : -1; });\n  return {items: items.slice(0, 40)};\n}\n\nfunction r_profileUpdate_(p, u) {\n  const patch = {};\n  if (p.name !== undefined) { const n = clean_(p.name, 60); if (!n) throw appErr_('Nama tidak boleh kosong'); patch.name = n; }\n  if (p.email !== undefined) patch.email = p.email ? validEmail_(p.email) : '';\n  updateRow_('Users', u._row, patch);\n  return {user: pubUser_(Object.assign(u, patch))};\n}\n\n/* ===================== KASIR / STAFF ===================== */\nfunction r_custLookup_(p) {\n  return {customer: custView_(resolveCustomer_(p.query))};\n}\n\n/** Tambah stamp ke event pilihan kasir. Stamp mengisi kartu terbuka; jika penuh, otomatis membuat kartu baru\n *  (maks. max_open_cards kartu belum selesai per pelanggan per event). */\nfunction r_stampAdd_(p, staff) {\n  const s = settings_();\n  return withLock_(function () { const r = stampCore_(p, staff, s); try { const u = userById_(p.userId); notifyRewardIfReady_(r.customer, u); notifyNearIfReady_(r.customer, u); } catch (e) {} return r; });\n}\n\n/** Inti penambahan stamp untuk satu pelanggan di satu event. Harus dipanggil di dalam lock. */\nfunction stampCore_(p, staff, s) {\n  const qty = Math.round(Number(p.qty));\n  if (!(qty >= 1 && qty <= s.max_qty_per_add)) throw appErr_('Jumlah stamp harus 1–' + s.max_qty_per_add);\n  {\n    const u = userById_(p.userId);\n    if (!u || u.active === 'N') throw appErr_('Pelanggan tidak ditemukan');\n    const camp = findOne_('Campaigns', 'id', p.campaignId);\n    if (!camp || camp.active === 'N') throw appErr_('Event stamp tidak ditemukan');\n    if (!campState_(camp).running) throw appErr_('Event \"' + camp.name + '\" sedang tidak berlangsung');\n    const rs = activeRewards_(camp.id);\n    if (!rs.length) throw appErr_('Event ini belum punya reward. Atur dulu di menu Admin.');\n    const maxReq = rs[rs.length - 1].required;\n\n    const cache = CacheService.getScriptCache(), ck = 'CD_' + u.user_id + '_' + camp.id, cd = s.cooldown_minutes;\n    if (cd > 0 && cache.get(ck) && !(p.force && staff.role === 'admin') && !p.skipCooldown) {\n      const mins = Math.max(1, Math.ceil((Number(cache.get(ck)) + cd * 60000 - Date.now()) / 60000));\n      throw appErr_('Pelanggan ini baru dapat stamp di event ini. Tunggu ±' + mins + ' menit lagi.', 'COOLDOWN');\n    }\n\n    const limit = s.max_open_cards;\n    const cards = cardsOf_(u.user_id).filter(function (k) { return k.campaign_id === camp.id && k.status === 'active'; }).sort(byCreated_);\n    let cur = cards.filter(function (k) { return (Number(k.stamps) || 0) < maxReq; })[0] || null;\n    let remaining = qty, created = 0;\n    const plan = [];\n    while (remaining > 0) {   // simulasi dulu; tulis ke sheet hanya jika semua muat dalam batas kartu\n      if (!cur) {\n        if (cards.length + created >= limit) throw appErr_('Pelanggan sudah punya ' + limit + ' kartu yang belum selesai di event ini. Tukar reward dulu.', 'CARD_LIMIT');\n        created++;\n        cur = {_new: true, card_id: newId_('CRD'), user_id: u.user_id, campaign_id: camp.id, stamps: 0, claimed_ids: '', status: 'active', created_at: nowStr_(), completed_at: ''};\n      }\n      if (plan.indexOf(cur) < 0) plan.push(cur);\n      const put = Math.min(maxReq - (Number(cur.stamps) || 0), remaining);\n      cur.stamps = (Number(cur.stamps) || 0) + put;\n      cur._put = (cur._put || 0) + put;\n      remaining -= put;\n      if (cur.stamps >= maxReq) cur = null;\n    }\n    plan.forEach(function (k) {\n      if (k._new) appendObj_('Cards', k); else updateRow_('Cards', k._row, {stamps: k.stamps});\n      appendObj_('Stamps', {id: newId_('STP'), user_id: u.user_id, customer_name: u.name, qty: k._put, type: 'earn',\n        by_user: staff.user_id, by_name: staff.name, note: clean_(p.note, 80), ts: nowStr_(), stamp_type: camp.id, card_id: k.card_id});\n    });\n    const patch = {total_earned: (Number(u.total_earned) || 0) + qty};\n    updateRow_('Users', u._row, patch);\n    if (cd > 0) cache.put(ck, String(Date.now()), Math.min(cd * 60, 21600));\n    touch_(u.user_id);\n    return {customer: custView_(Object.assign(u, patch)), newCards: created};\n  }\n}\n\n/** Klaim satu reward pada satu kartu. Stamp tidak dikurangi; kartu selesai bila semua reward-nya sudah diklaim. */\nfunction r_rewardRedeem_(p, staff) {\n  return withLock_(function () { return redeemCore_(p, staff); });\n}\n\nfunction redeemCore_(p, staff) {\n  {\n    const u = userById_(p.userId);\n    if (!u) throw appErr_('Pelanggan tidak ditemukan');\n    const card = findOne_('Cards', 'card_id', p.cardId);\n    if (!card || card.user_id !== u.user_id || card.status !== 'active') throw appErr_('Kartu tidak ditemukan');\n    const camp = findOne_('Campaigns', 'id', card.campaign_id);\n    if (!camp || !campState_(camp).redeemable) throw appErr_('Masa penukaran kartu ini sudah berakhir');\n    const rs = activeRewards_(card.campaign_id), r = rs.filter(function (x) { return x.id === p.rewardId; })[0];\n    if (!r) throw appErr_('Reward tidak ditemukan atau sudah dinonaktifkan');\n    const st = Number(card.stamps) || 0, claimed = splitIds_(card.claimed_ids);\n    if (claimed.indexOf(r.id) >= 0) throw appErr_('Reward ini sudah diklaim di kartu tersebut');\n    if (st < r.required) throw appErr_('Stamp belum cukup (' + st + '/' + r.required + ')');\n    claimed.push(r.id);\n    const done = rs.every(function (x) { return claimed.indexOf(x.id) >= 0; });\n    updateRow_('Cards', card._row, {claimed_ids: claimed.join(','), status: done ? 'done' : 'active', completed_at: done ? nowStr_() : ''});\n    const patch = {total_redeemed: (Number(u.total_redeemed) || 0) + 1};\n    updateRow_('Users', u._row, patch);\n    appendObj_('Redemptions', {id: newId_('RDM'), user_id: u.user_id, customer_name: u.name, reward_name: r.name, stamps_used: r.required,\n      by_user: staff.user_id, by_name: staff.name, ts: nowStr_(), reward_id: r.id, stamp_type: card.campaign_id, card_id: card.card_id});\n    touch_(u.user_id);\n    return {customer: custView_(Object.assign(u, patch)), cardDone: done};\n  }\n}\n\n/* ---------- MODE GRUP: banyak pelanggan sekaligus ----------\n * Tiap orang diproses sendiri-sendiri (lock per orang). Jika satu gagal (jeda, batas kartu, dll.)\n * yang lain tetap diproses, dan hasil per orang dikembalikan agar kasir melihat alasannya. */\nconst BATCH_MAX = 20;\n\nfunction batchRun_(items, fn) {\n  return items.map(function (it) {\n    try {\n      const r = withLock_(function () { return fn(it); });\n      return Object.assign({userId: it.userId, ok: true}, r);\n    } catch (e) {\n      if (!e.code) console.error(e && e.stack || e);\n      return {userId: it.userId, ok: false, error: e.code ? e.message : 'Gagal diproses', code: e.code || 'ERR'};\n    }\n  });\n}\n\nfunction batchItems_(p) {\n  const items = p.items;\n  if (!items || !items.length) throw appErr_('Belum ada pelanggan di grup');\n  if (items.length > BATCH_MAX) throw appErr_('Maksimal ' + BATCH_MAX + ' pelanggan sekali proses');\n  return items;\n}\n\nfunction r_stampBatch_(p, staff) {\n  const items = batchItems_(p), s = settings_();\n  return {results: batchRun_(items, function (it) {\n    return stampCore_({userId: it.userId, campaignId: p.campaignId, qty: it.qty, note: p.note, force: p.force}, staff, s);\n  })};\n}\n\nfunction r_redeemBatch_(p, staff) {\n  const items = batchItems_(p);\n  return {results: batchRun_(items, function (it) {\n    return redeemCore_({userId: it.userId, cardId: it.cardId, rewardId: it.rewardId}, staff);\n  })};\n}\n\nfunction r_stampAdjust_(p, admin) {\n  const delta = Math.round(Number(p.delta));\n  const note = clean_(p.note, 80);\n  if (!delta || Math.abs(delta) > 100) throw appErr_('Jumlah koreksi tidak valid');\n  if (!note) throw appErr_('Alasan koreksi wajib diisi');\n  return withLock_(function () {\n    const u = userById_(p.userId);\n    if (!u) throw appErr_('Pelanggan tidak ditemukan');\n    const card = findOne_('Cards', 'card_id', p.cardId);\n    if (!card || card.user_id !== u.user_id || card.status !== 'active') throw appErr_('Pilih kartu yang akan dikoreksi');\n    const rs = activeRewards_(card.campaign_id), maxReq = rs.length ? rs[rs.length - 1].required : 0;\n    const next = (Number(card.stamps) || 0) + delta;\n    if (next < 0 || next > maxReq) throw appErr_('Stamp kartu harus antara 0 dan ' + maxReq);\n    updateRow_('Cards', card._row, {stamps: next});\n    appendObj_('Stamps', {id: newId_('STP'), user_id: u.user_id, customer_name: u.name, qty: delta, type: 'adjust',\n      by_user: admin.user_id, by_name: admin.name, note: note, ts: nowStr_(), stamp_type: card.campaign_id, card_id: card.card_id});\n    touch_(u.user_id);\n    return {customer: custView_(u)};\n  });\n}\n\nfunction r_staffActivity_(p, staff) {\n  const names = campNames_(), items = [];\n  const mine = function (r) { return staff.role === 'admin' || r.by_user === staff.user_id; };\n  const stamps = tail_('Stamps', 80), voided = {};\n  stamps.forEach(function (r) { if (r.void_of) voided[r.void_of] = 1; });\n  stamps.forEach(function (r) {\n    if (mine(r)) items.push({id: r.id, kind: r.type, name: r.customer_name, qty: Number(r.qty), by: r.by_name, note: r.note, ts: r.ts, campaign: names[r.stamp_type || DEFAULT_TYPE] || '', voided: !!voided[r.id]});\n  });\n  tail_('Redemptions', 80).forEach(function (r) {\n    if (mine(r)) items.push({kind: 'redeem', name: r.customer_name, qty: Number(r.stamps_used), by: r.by_name, note: r.reward_name, ts: r.ts, campaign: names[r.stamp_type || DEFAULT_TYPE] || ''});\n  });\n  if (staff.role === 'admin') {\n    const led = tail_('PointsLedger', 60), vv = {};\n    led.forEach(function (r) { if (r.source === 'void' && r.ref) vv[r.ref] = 1; });\n    led.forEach(function (r) {\n      if (r.source === 'void') return;\n      items.push({id: r.id, kind: 'vp', name: r.username || '?', qty: Number(r.amount), by: r.by_name || '', note: r.source + (r.note ? ': ' + r.note : ''), ts: r.ts, campaign: '', voided: !!vv[r.id]});\n    });\n  }\n  items.sort(function (a, b) { return a.ts < b.ts ? 1 : -1; });\n  return {items: items.slice(0, 30)};\n}\n\nfunction resolveCustomer_(q) {\n  q = String(q || '').trim();\n  if (!q) throw appErr_('Masukkan nomor HP, username, atau kode member');\n  let u = null;\n  if (q.indexOf('LS1.') === 0) {\n    const parts = q.split('.');\n    if (parts.length !== 4 || parts[3] !== qrSig_(parts[1], parts[2])) throw appErr_('QR tidak valid');\n    const age = Date.now() / 1000 - Number(parts[2]);\n    if (age > QR_TTL + 30 || age < -60) throw appErr_('QR kedaluwarsa. Minta pelanggan menyegarkan QR-nya.');\n    u = findOne_('Users', 'member_code', parts[1]);\n  } else if (/^\\+?[\\d\\s-]{8,}$/.test(q)) {                 // terlihat seperti nomor HP\n    u = userByPhone_(normPhone_(q));\n  } else if (/^LS-[A-Za-z0-9]{6}$/i.test(q)) {              // kode member lengkap\n    u = findOne_('Users', 'member_code', q.toUpperCase());\n  } else {                                                    // username dulu, lalu kode member 6 karakter tanpa \"LS-\"\n    u = findOne_('Users', 'username_key', q.replace(/^@/, '').toLowerCase());\n    if (!u && /^[A-Za-z0-9]{6}$/.test(q)) u = findOne_('Users', 'member_code', 'LS-' + q.toUpperCase());\n  }\n  if (!u) throw appErr_('Pelanggan tidak ditemukan');\n  if (u.active === 'N') throw appErr_('Akun pelanggan dinonaktifkan');\n  return u;\n}\n\n/* ===================== ADMIN: EVENT ===================== */\nfunction r_eventsList_() {\n  const rows = readAll_('Events').map(eventPub_);\n  rows.sort(function (a, b) { return a.sort - b.sort; });\n  return {events: rows};\n}\n\nfunction r_eventSave_(p) {\n  const title = clean_(p.title, 80);\n  if (!title) throw appErr_('Judul event wajib diisi');\n  const start = dt_(p.start), end = dt_(p.end);\n  if (start && end && end < start) throw appErr_('Waktu selesai harus setelah waktu mulai');\n  const obj = {\n    title: title, subtitle: clean_(p.subtitle, 140), badge: clean_(p.badge, 30) || 'Sedang Berlangsung',\n    image_url: normUrl_(p.image, true), link: normUrl_(p.link, false),\n    start: start, end: end, active: p.active === false ? 'N' : 'Y', sort: Math.round(Number(p.sort)) || 0\n  };\n  return withLock_(function () {\n    if (p.id) {\n      const e = findOne_('Events', 'id', p.id);\n      if (!e) throw appErr_('Event tidak ditemukan');\n      updateRow_('Events', e._row, obj);\n    } else {\n      obj.id = newId_('EVT'); obj.created_at = nowStr_();\n      appendObj_('Events', obj);\n    }\n    return r_eventsList_();\n  });\n}\n\nfunction r_eventDelete_(p) {\n  return withLock_(function () {\n    const e = findOne_('Events', 'id', p.id);\n    if (e) delRow_('Events', e._row);\n    return r_eventsList_();\n  });\n}\n\nfunction activeEvents_() {\n  const now = fmt_(new Date(), 'yyyy-MM-dd HH:mm');\n  return readAll_('Events').filter(function (e) {\n    return e.active !== 'N' && (!e.start || String(e.start) <= now) && (!e.end || String(e.end) >= now);\n  }).map(eventPub_).sort(function (a, b) { return a.sort - b.sort; });\n}\n\nfunction eventPub_(e) {\n  return {id: e.id, title: e.title, subtitle: e.subtitle, badge: e.badge, image: e.image_url, link: e.link,\n    start: String(e.start || '').replace(' ', 'T'), end: String(e.end || '').replace(' ', 'T'),\n    active: e.active !== 'N', sort: Number(e.sort) || 0};\n}\n\n/* ===================== ADMIN: PENGATURAN, STATISTIK, PENGGUNA ===================== */\nfunction r_settingsGet_() {\n  const s = settings_();\n  return {fields: Object.keys(SETTING_DEFS).map(function (k) {\n    const d = SETTING_DEFS[k];\n    return {key: k, label: d.label, type: d.t, value: s[k], min: d.min, max: d.max};\n  })};\n}\n\nfunction r_settingsSave_(p) {\n  const vals = p.values || {};\n  return withLock_(function () {\n    Object.keys(vals).forEach(function (k) {\n      const d = SETTING_DEFS[k];\n      if (!d) return;\n      let v = vals[k];\n      if (d.t === 'n') {\n        v = Math.round(Number(v));\n        if (!isFinite(v) || v < d.min || v > d.max) throw appErr_(d.label + ' harus antara ' + d.min + ' dan ' + d.max);\n      } else if (d.t === 'c') {\n        if (!/^#[0-9a-fA-F]{6}$/.test(String(v))) throw appErr_('Format warna tidak valid');\n      } else {\n        v = clean_(v, d.max);\n        if (!v && k !== 'reward_terms') throw appErr_(d.label + ' tidak boleh kosong');\n      }\n      const row = findOne_('Settings', 'key', k);\n      if (row) updateRow_('Settings', row._row, {value: v});\n      else appendObj_('Settings', {key: k, value: v, description: d.label});\n    });\n    CacheService.getScriptCache().remove('SETTINGS');\n    return r_settingsGet_();\n  });\n}\n\nfunction r_stats_() {\n  const today = fmt_(new Date(), 'yyyy-MM-dd'), month = fmt_(new Date(), 'yyyy-MM');\n  let stampsToday = 0, redeemToday = 0, redeemMonth = 0;\n  tail_('Stamps', 3000).forEach(function (r) { if (r.type === 'earn' && String(r.ts).indexOf(today) === 0) stampsToday += Number(r.qty); });\n  tail_('Redemptions', 3000).forEach(function (r) {\n    if (String(r.ts).indexOf(today) === 0) redeemToday++;\n    if (String(r.ts).indexOf(month) === 0) redeemMonth++;\n  });\n  const users = readAll_('Users');\n  return {\n    customers: users.filter(function (u) { return u.role === 'customer'; }).length,\n    staff: users.filter(function (u) { return u.role !== 'customer'; }).length,\n    stampsToday: stampsToday, redeemToday: redeemToday, redeemMonth: redeemMonth\n  };\n}\n\nfunction r_userSearch_(p) {\n  const q = String(p.q || '').trim().toLowerCase();\n  let digits = q.replace(/\\D/g, '');\n  if (digits.charAt(0) === '0') digits = COUNTRY_CODE + digits.slice(1);\n  const out = [];\n  readAll_('Users').forEach(function (u) {\n    const hit = q ? (String(u.name).toLowerCase().indexOf(q) >= 0 || String(u.username_key || '').indexOf(q) >= 0 || (digits && String(u.phone).indexOf(digits) >= 0) || String(u.member_code).toLowerCase().indexOf(q) >= 0)\n                  : u.role !== 'customer';\n    if (hit && out.length < 20) out.push({id: u.user_id, name: u.name, username: u.username || '', gender: u.gender || '', phone: u.phone, role: u.role, active: u.active !== 'N',\n      stamps: Number(u.total_earned) || 0, vp: Number(u.vp_total) || 0, memberCode: u.member_code});\n  });\n  return {users: out};\n}\n\nfunction r_userUpdate_(p, admin) {\n  return withLock_(function () {\n    const u = userById_(p.userId);\n    if (!u) throw appErr_('Pengguna tidak ditemukan');\n    if (u.user_id === admin.user_id) throw appErr_('Anda tidak bisa mengubah akun sendiri');\n    const patch = {};\n    if (p.role !== undefined) {\n      if (ALL.indexOf(p.role) < 0) throw appErr_('Peran tidak valid');\n      patch.role = p.role;\n    }\n    if (p.active !== undefined) patch.active = p.active ? 'Y' : 'N';\n    if (p.name !== undefined) { const n = clean_(p.name, 60); if (!n) throw appErr_('Nama lengkap tidak boleh kosong'); patch.name = n; }\n    if (p.gender !== undefined) patch.gender = normGender_(p.gender);\n    if (p.username !== undefined) {\n      const un = normUsername_(p.username);\n      if (usernameTaken_(un.key, u.user_id)) throw appErr_('Username sudah dipakai. Pilih yang lain.', 'USERNAME_TAKEN');\n      patch.username = un.name; patch.username_key = un.key;\n    }\n    updateRow_('Users', u._row, patch);\n    if (patch.active === 'N') deleteWhere_('Sessions', 'user_id', u.user_id);\n    return {ok: true};\n  });\n}\n\n/* ===================== PENGIRIMAN OTP ===================== */\nfunction waEnabled_() { return !!prop_('FONNTE_TOKEN') || prop_('DEBUG_OTP') === 'true'; }\n\n/** Contoh provider: Fonnte (https://fonnte.com). Ganti isi fungsi ini untuk provider lain. */\nfunction sendWhatsApp_(phone, message) {\n  const token = prop_('FONNTE_TOKEN');\n  if (!token) {\n    if (prop_('DEBUG_OTP') === 'true') { Logger.log('[DEBUG OTP] %s -> %s', phone, message); return; }\n    throw appErr_('WhatsApp belum dikonfigurasi');\n  }\n  const res = UrlFetchApp.fetch('https://api.fonnte.com/send', {\n    method: 'post', headers: {Authorization: token}, payload: {target: phone, message: message}, muteHttpExceptions: true\n  });\n  let body = {};\n  try { body = JSON.parse(res.getContentText()); } catch (e) {}\n  if (res.getResponseCode() !== 200 || body.status === false) {\n    console.error('Fonnte error: ' + res.getContentText());\n    throw appErr_('Gagal mengirim WhatsApp. Coba lagi atau gunakan email.');\n  }\n}\n\n/* ===================== HELPER: DATA LAYER (Supabase / PostgreSQL) ===================== */\n// Satu tabel PostgreSQL per nama di HEADERS (kolom teks). Kolom rn (identity) = nomor baris stabil, dipakai sebagai _row.\nfunction tname_(name) { return name.toLowerCase(); }\nfunction dbSelect_(table, q) { return JSON.parse(__DB.select(table, JSON.stringify(q || {}))); }\nfunction str_(v) { return v === undefined || v === null ? '' : String(v); }\n\nfunction rowObj_(name, r) {\n  const o = {_row: Number(r.rn)};\n  HEADERS[name].forEach(function (k) { o[k] = str_(r[k]); });\n  return o;\n}\n\n// Tabel kecil yang jarang berubah dicache 5 menit agar halaman cepat dimuat; cache dihapus tiap ada perubahan.\nconst CACHED_TABLES = {Campaigns: 1, Rewards: 1, Events: 1, Games: 1, Tiers: 1};\nconst CHUNK_ = 30000; // batas cache 100 KB per nilai; data besar dipecah per 30000 karakter\n\nfunction cacheGetBig_(key) {\n  const c = CacheService.getScriptCache(), meta = c.get(key + '#n');\n  if (!meta) return null;\n  const n = Number(meta), keys = [];\n  for (let i = 0; i < n; i++) keys.push(key + '#' + i);\n  const got = c.getAll(keys);\n  let out = '';\n  for (let i = 0; i < n; i++) { const part = got[keys[i]]; if (part == null) return null; out += part; }\n  return out;\n}\nfunction cachePutBig_(key, str, ttl) {\n  const c = CacheService.getScriptCache(), obj = {};\n  let n = 0;\n  for (let i = 0; i < str.length; i += CHUNK_) obj[key + '#' + (n++)] = str.substring(i, i + CHUNK_);\n  obj[key + '#n'] = String(n);\n  c.putAll(obj, ttl);\n}\nfunction cacheDelBig_(key) {\n  const c = CacheService.getScriptCache(), meta = c.get(key + '#n');\n  const keys = [key + '#n'];\n  for (let i = 0, n = Number(meta) || 0; i < n; i++) keys.push(key + '#' + i);\n  c.removeAll(keys);\n}\n\nfunction invalidate_(name) { if (CACHED_TABLES[name]) cacheDelBig_('TBL_' + name); }\n\nfunction readAll_(name) {\n  const cached = CACHED_TABLES[name];\n  if (cached) { try { const hit = cacheGetBig_('TBL_' + name); if (hit) return JSON.parse(hit); } catch (e) {} }\n  const rows = dbSelect_(tname_(name), {all: true}).map(function (r) { return rowObj_(name, r); });\n  if (cached) { try { cachePutBig_('TBL_' + name, JSON.stringify(rows), 300); } catch (e) {} }\n  return rows;\n}\n\n/** Baris yang cocok dengan filter [[kolom, op, nilai]]; op: eq neq lt lte gt gte like in. */\nfunction queryRows_(name, filters, extra) {\n  const q = Object.assign({filters: filters}, extra || {});\n  if (!q.limit) q.all = true;\n  return dbSelect_(tname_(name), q).map(function (r) { return rowObj_(name, r); });\n}\nfunction findAll_(name, col, value) { return value === '' || value == null ? [] : queryRows_(name, [[col, 'eq', String(value)]]); }\n\nfunction delRow_(name, row) { __DB.remove(tname_(name), JSON.stringify([['rn', 'eq', row]])); invalidate_(name); }\n\nfunction tail_(name, n) {\n  return dbSelect_(tname_(name), {order: 'rn.desc', limit: n}).reverse().map(function (r) { return rowObj_(name, r); });\n}\n\nfunction findOne_(name, col, value) {\n  if (value === '' || value == null) return null;\n  const r = dbSelect_(tname_(name), {filters: [[col, 'eq', String(value)]], limit: 1});\n  return r.length ? rowObj_(name, r[0]) : null;\n}\n\nfunction rowStrings_(name, obj) { const o = {}; HEADERS[name].forEach(function (k) { o[k] = str_(obj[k]); }); return o; }\n\nfunction appendObj_(name, obj) {\n  const r = JSON.parse(__DB.insert(tname_(name), JSON.stringify([rowStrings_(name, obj)])));\n  invalidate_(name);\n  return Number(r[0].rn);\n}\n\nfunction appendMany_(name, objs) {\n  if (!objs.length) return;\n  __DB.insert(tname_(name), JSON.stringify(objs.map(function (o) { return rowStrings_(name, o); })));\n  invalidate_(name);\n}\n\nfunction updateRow_(name, row, patch) {\n  const p = {};\n  Object.keys(patch).forEach(function (k) { if (HEADERS[name].indexOf(k) >= 0) p[k] = str_(patch[k]); });\n  if (Object.keys(p).length) __DB.update(tname_(name), row, JSON.stringify(p));\n  invalidate_(name);\n}\n\nfunction deleteWhere_(name, col, value) {\n  if (value === '' || value == null) return;\n  __DB.remove(tname_(name), JSON.stringify([[col, 'eq', String(value)]]));\n  invalidate_(name);\n}\n\nfunction userByPhone_(phone) { return findOne_('Users', 'phone', phone); }\nfunction userById_(id) { return findOne_('Users', 'user_id', id); }\n\nfunction createUser_(phone, name, email, extra) {\n  extra = extra || {};\n  const u = {\n    user_id: newId_('USR'), phone: phone, name: clean_(name, 60) || 'Pelanggan', email: email || '',\n    role: phone === adminPhone_() ? 'admin' : 'customer', member_code: uniqueMemberCode_(),\n    stamps: 0, total_earned: 0, total_redeemed: 0, active: 'Y', created_at: nowStr_(), last_login: nowStr_(), last_stamp_at: '', claimed_ids: '',\n    username: extra.username || '', username_key: String(extra.username || '').toLowerCase(), gender: extra.gender || '',\n    vp_total: 0, vp_month: 0, vp_month_key: '', grp_change_key: '', grp_change_ts: '', auto_created: extra.auto ? 'Y' : ''\n  };\n  u._row = appendObj_('Users', u);\n  return u;\n}\n\nfunction uniqueMemberCode_() {\n  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n  for (let t = 0; t < 20; t++) {\n    let c = 'LS-';\n    for (let i = 0; i < 6; i++) c += chars.charAt(Math.floor(Math.random() * chars.length));\n    if (!findOne_('Users', 'member_code', c)) return c;\n  }\n  throw appErr_('Gagal membuat kode member');\n}\n\n/* ===================== HELPER: PENGATURAN & FORMAT ===================== */\nfunction settings_() {\n  const cache = CacheService.getScriptCache(), hit = cache.get('SETTINGS');\n  if (hit) return JSON.parse(hit);\n  const out = {};\n  Object.keys(SETTING_DEFS).forEach(function (k) { out[k] = SETTING_DEFS[k].d; });\n  readAll_('Settings').forEach(function (r) {\n    const k = String(r.key), d = SETTING_DEFS[k];\n    if (!d) return;\n    if (d.t === 'n') { const n = Number(r.value); out[k] = (r.value !== '' && isFinite(n)) ? n : d.d; }\n    else if (String(r.value) !== '' || k === 'reward_terms') out[k] = String(r.value);\n  });\n  cache.put('SETTINGS', JSON.stringify(out), 120);\n  return out;\n}\n\nfunction pubSettings_(s) {\n  return {cafe_name: s.cafe_name, tagline: s.tagline, theme_color: s.theme_color, reward_terms: s.reward_terms, max_qty_per_add: s.max_qty_per_add};\n}\n\nfunction pubUser_(u) {\n  return {id: u.user_id, phone: u.phone, name: u.name, email: u.email || '', role: u.role, memberCode: u.member_code,\n    username: u.username || '', gender: u.gender || '', needProfile: !u.username || !u.gender,\n    stamps: Number(u.stamps) || 0, totalEarned: Number(u.total_earned) || 0, totalRedeemed: Number(u.total_redeemed) || 0};\n}\n\n/* ===================== KARTU, EVENT STAMP (CAMPAIGN), REWARD ===================== */\n/* Versi data per pengguna disimpan di tabel pings dengan topik acak (tak bisa ditebak). HP memeriksanya langsung ke Supabase\n   tanpa memanggil server; bila berubah barulah HP meminta data baru. */\nfunction pingTopic_(uid) { return sha256_('ping|' + secret_() + '|' + uid).slice(0, 32); }\nfunction ver_(uid) { return __DB.getPing(pingTopic_(uid)) || '0'; }\nfunction pingMany_(uids) { const t = String(Date.now()); __DB.pingMany(JSON.stringify(uids.map(function (id) { return [pingTopic_(id), t]; }))); }\nfunction touch_(uid) { __DB.pingMany(JSON.stringify([[pingTopic_(uid), String(Date.now())]])); }\nfunction splitIds_(v) { return String(v || '').split(',').filter(function (x) { return x; }); }\nfunction byCreated_(a, b) {\n  const x = String(a.created_at), y = String(b.created_at);\n  return x < y ? -1 : x > y ? 1 : (String(a.card_id) < String(b.card_id) ? -1 : 1);\n}\nfunction toLocal_(v) { return String(v || '').replace(' ', 'T'); }\n\nfunction cardsOf_(uid) { return findAll_('Cards', 'user_id', uid); }\n\n/** Status waktu sebuah event: running = boleh diberi stamp; redeemable = reward kartunya masih boleh ditukar. */\nfunction campState_(c) {\n  const now = fmt_(new Date(), 'yyyy-MM-dd HH:mm');\n  const start = String(c.start || ''), end = String(c.end || ''), until = String(c.redeem_until || end || '');\n  const active = c.active !== 'N', started = !start || start <= now, ended = !!end && end < now;\n  return {running: active && started && !ended, redeemable: active && started && (!until || until >= now), until: until};\n}\n\nfunction cardView_(k, rs, maxReq, number) {\n  const st = Number(k.stamps) || 0, claimed = splitIds_(k.claimed_ids);\n  const ms = rs.map(function (r) {\n    return {id: r.id, name: r.name, description: r.description, required: r.required,\n      status: claimed.indexOf(r.id) >= 0 ? 'claimed' : (st >= r.required ? 'available' : 'locked'), remaining: Math.max(0, r.required - st)};\n  });\n  return {id: k.card_id || '', number: number, stamps: st, maxRequired: maxReq, filled: Math.min(st, maxReq),\n    state: (maxReq > 0 && st >= maxReq) ? 'full' : 'open', milestones: ms,\n    availableCount: ms.filter(function (m) { return m.status === 'available'; }).length,\n    next: ms.filter(function (m) { return m.status === 'locked'; })[0] || null};\n}\n\n/** Seluruh data kartu pelanggan, dikelompokkan per event stamp. */\nfunction custView_(u) {\n  const limit = settings_().max_open_cards;\n  const rewards = {};\n  allActiveRewards_().forEach(function (r) { (rewards[r.campaignId] = rewards[r.campaignId] || []).push(r); });\n  const cards = cardsOf_(u.user_id).filter(function (k) { return k.status === 'active'; });\n  const campaigns = [];\n  readAll_('Campaigns').filter(function (c) { return c.active !== 'N'; })\n    .sort(function (a, b) { return (Number(a.sort) || 0) - (Number(b.sort) || 0); })\n    .forEach(function (c) {\n      const st = campState_(c), rs = rewards[c.id] || [], maxReq = rs.length ? rs[rs.length - 1].required : 0;\n      const mine = (st.running || st.redeemable) ? cards.filter(function (k) { return k.campaign_id === c.id; }).sort(byCreated_) : [];\n      let views = mine.map(function (k, i) { return cardView_(k, rs, maxReq, i + 1); });\n      if (!st.running) views = views.filter(function (v) { return v.availableCount > 0; });  // event lewat: hanya kartu yang bisa ditukar\n      const hasOpen = views.some(function (v) { return v.state === 'open'; });\n      const limitReached = st.running && maxReq > 0 && !hasOpen && views.length >= limit;\n      if (st.running && maxReq > 0 && !hasOpen && !limitReached) views.push(cardView_({card_id: '', stamps: 0, claimed_ids: ''}, rs, maxReq, views.length + 1));\n      if (!st.running && !views.length) return;\n      campaigns.push({id: c.id, name: c.name, description: c.description, icon: c.icon || '☕', start: toLocal_(c.start), end: toLocal_(c.end),\n        redeemUntil: toLocal_(st.until), running: st.running, redeemable: st.redeemable, canStamp: st.running && maxReq > 0,\n        limitReached: limitReached, maxCards: limit, maxRequired: maxReq, cards: views});\n    });\n  return {id: u.user_id, notif: unreadCount_(u.user_id), name: u.name, username: u.username || '', phone: u.phone, memberCode: u.member_code,\n    totalEarned: Number(u.total_earned) || 0, totalRedeemed: Number(u.total_redeemed) || 0, vp: vpView_(u), campaigns: campaigns};\n}\n\nfunction campaignPub_(c) {\n  return {id: c.id, name: c.name, description: c.description, icon: c.icon || '☕', start: toLocal_(c.start), end: toLocal_(c.end),\n    redeemUntil: toLocal_(c.redeem_until), active: c.active !== 'N', sort: Number(c.sort) || 0};\n}\nfunction campNames_() { const o = {}; readAll_('Campaigns').forEach(function (c) { o[c.id] = c.name; }); return o; }\n\nfunction r_campaignsList_() {\n  const list = readAll_('Campaigns').map(campaignPub_);\n  list.sort(function (a, b) { return a.sort - b.sort; });\n  return {campaigns: list};\n}\n\nfunction r_campaignSave_(p) {\n  const name = clean_(p.name, 60);\n  if (!name) throw appErr_('Nama event stamp wajib diisi');\n  const start = dt_(p.start), end = dt_(p.end), until = dt_(p.redeemUntil);\n  if (start && end && end < start) throw appErr_('Waktu selesai harus setelah waktu mulai');\n  if (until && end && until < end) throw appErr_('Batas penukaran reward tidak boleh sebelum event selesai');\n  if (until && !end) throw appErr_('Batas penukaran hanya dipakai jika event punya waktu selesai');\n  const obj = {name: name, description: clean_(p.description, 140), icon: clean_(p.icon, 4) || '☕', start: start, end: end,\n    redeem_until: until, active: p.active === false ? 'N' : 'Y', sort: Math.round(Number(p.sort)) || 0};\n  return withLock_(function () {\n    if (p.id) {\n      const c = findOne_('Campaigns', 'id', p.id);\n      if (!c) throw appErr_('Event stamp tidak ditemukan');\n      updateRow_('Campaigns', c._row, obj);\n    } else {\n      obj.id = newId_('CMP'); obj.created_at = nowStr_();\n      appendObj_('Campaigns', obj);\n    }\n    return r_campaignsList_();\n  });\n}\n\nfunction r_campaignDelete_(p) {\n  if (p.id === DEFAULT_TYPE) throw appErr_('Event bawaan tidak bisa dihapus. Nonaktifkan saja.');\n  return withLock_(function () {\n    if (findOne_('Cards', 'campaign_id', p.id)) throw appErr_('Event ini sudah punya kartu pelanggan. Nonaktifkan saja agar riwayat aman.');\n    const c = findOne_('Campaigns', 'id', p.id);\n    if (c) { deleteWhere_('Rewards', 'stamp_type', p.id); delRow_('Campaigns', c._row); }\n    return r_campaignsList_();\n  });\n}\n\nfunction rewardPub_(r) {\n  return {id: r.id, name: r.name, description: r.description, required: Number(r.stamps_required) || 0,\n    active: r.active !== 'N', sort: Number(r.sort) || 0, campaignId: r.stamp_type || DEFAULT_TYPE};\n}\n\nfunction allActiveRewards_() {\n  return readAll_('Rewards').filter(function (r) { return r.active !== 'N'; }).map(rewardPub_)\n    .sort(function (a, b) { return a.required - b.required || a.sort - b.sort; });\n}\nfunction activeRewards_(campaignId) {\n  campaignId = campaignId || DEFAULT_TYPE;\n  return allActiveRewards_().filter(function (r) { return r.campaignId === campaignId; });\n}\n\nfunction r_rewardsList_() {\n  const list = readAll_('Rewards').map(rewardPub_);\n  list.sort(function (a, b) { return a.required - b.required || a.sort - b.sort; });\n  return {rewards: list, campaigns: r_campaignsList_().campaigns};\n}\n\nfunction r_rewardSave_(p) {\n  const name = clean_(p.name, 80);\n  const req = Math.round(Number(p.required));\n  if (!name) throw appErr_('Nama reward wajib diisi');\n  if (!(req >= 1 && req <= 100)) throw appErr_('Jumlah stamp milestone harus 1–100');\n  if (!findOne_('Campaigns', 'id', p.campaignId)) throw appErr_('Pilih event stamp untuk reward ini');\n  const obj = {name: name, description: clean_(p.description, 140), stamps_required: req, stamp_type: p.campaignId,\n    active: p.active === false ? 'N' : 'Y', sort: Math.round(Number(p.sort)) || 0};\n  return withLock_(function () {\n    if (p.id) {\n      const r = findOne_('Rewards', 'id', p.id);\n      if (!r) throw appErr_('Reward tidak ditemukan');\n      updateRow_('Rewards', r._row, obj);\n    } else {\n      obj.id = newId_('RWD'); obj.created_at = nowStr_();\n      appendObj_('Rewards', obj);\n    }\n    return r_rewardsList_();\n  });\n}\n\nfunction r_rewardDelete_(p) {\n  return withLock_(function () {\n    const r = findOne_('Rewards', 'id', p.id);\n    if (r) delRow_('Rewards', r._row);\n    return r_rewardsList_();\n  });\n}\n\nfunction tz_() { return Session.getScriptTimeZone(); }\nfunction fmt_(d, f) { return Utilities.formatDate(d, tz_(), f); }\nfunction nowStr_() { return fmt_(new Date(), 'yyyy-MM-dd HH:mm:ss'); }\nfunction parseTs_(str) { return Utilities.parseDate(String(str), tz_(), 'yyyy-MM-dd HH:mm:ss').getTime(); }\n\nfunction dt_(v) {\n  v = String(v || '').trim().replace('T', ' ');\n  if (!v) return '';\n  if (!/^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}$/.test(v)) throw appErr_('Format tanggal/waktu tidak valid');\n  return v;\n}\n\nfunction normUrl_(u, isImage) {\n  u = String(u || '').trim();\n  if (!u) return '';\n  if (!/^https:\\/\\//i.test(u)) throw appErr_('Link harus diawali https://');\n  if (u.length > 500) throw appErr_('Link terlalu panjang');\n  if (isImage) {\n    const m = u.match(/drive\\.google\\.com\\/file\\/d\\/([\\w-]+)/) || u.match(/drive\\.google\\.com\\/(?:open|uc)\\?(?:[^#]*&)?id=([\\w-]+)/);\n    if (m) return 'https://lh3.googleusercontent.com/d/' + m[1];\n  }\n  return u;\n}\n\nfunction normPhone_(p) {\n  let s = String(p || '').replace(/[^\\d+]/g, '');\n  if (s.charAt(0) === '+') s = s.slice(1);\n  if (s.charAt(0) === '0') s = COUNTRY_CODE + s.slice(1);\n  else if (s.charAt(0) === '8') s = COUNTRY_CODE + s;\n  if (!new RegExp('^' + COUNTRY_CODE + '\\\\d{8,12}$').test(s)) throw appErr_('Nomor HP tidak valid');\n  return s;\n}\n\nfunction validEmail_(e) {\n  e = String(e || '').trim().toLowerCase();\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(e) || e.length > 120) throw appErr_('Format email tidak valid');\n  return e;\n}\n\nfunction maskPhone_(p) { return p.slice(0, 5) + '****' + p.slice(-3); }\nfunction maskEmail_(e) { const a = e.split('@'); return a[0].charAt(0) + '***@' + a[1]; }\nfunction clean_(v, max) { return String(v == null ? '' : v).replace(/[\\u0000-\\u001F\\u007F]/g, ' ').trim().slice(0, max || 200); }\nfunction escHtml_(s) { return String(s).replace(/[&<>\"']/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'}[c]; }); }\n// ID berurutan & mudah dibaca: USR-0001, PTY-0001, VST-0001 ... (penghitung atomik di database)\nfunction fmtId_(prefix, n) { return prefix + '-' + ('0000' + n).slice(-Math.max(4, String(n).length)); }\nfunction newIds_(prefix, count) {\n  const first = __DB.nextIds(prefix, count), out = [];\n  for (let i = 0; i < count; i++) out.push(fmtId_(prefix, first + i));\n  return out;\n}\nfunction newId_(prefix) { return newIds_(prefix, 1)[0]; }\nfunction appErr_(msg, code) { const e = new Error(msg); e.code = code || 'APP'; return e; }\nfunction prop_(k) { return PropertiesService.getScriptProperties().getProperty(k); }\nfunction adminPhone_() { const a = prop_('ADMIN_PHONE'); if (!a) return ''; try { return normPhone_(a); } catch (e) { return ''; } }\n\n/* ===================== HELPER: KEAMANAN ===================== */\nfunction hex_(bytes) { return bytes.map(function (b) { return ('0' + (b < 0 ? b + 256 : b).toString(16)).slice(-2); }).join(''); }\nfunction sha256_(s) { return hex_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, s, Utilities.Charset.UTF_8)); }\n\nfunction secret_() {\n  let s = prop_('HMAC_SECRET');\n  if (!s) { s = Utilities.getUuid() + Utilities.getUuid(); PropertiesService.getScriptProperties().setProperty('HMAC_SECRET', s); }\n  return s;\n}\nfunction qrSig_(code, ts) { return hex_(Utilities.computeHmacSha256Signature(code + '.' + ts, secret_())).slice(0, 12); }\nfunction otpHash_(phone, code) { return sha256_(secret_() + phone + code); }\nfunction genOtp_() { return ('000000' + (parseInt(sha256_(Utilities.getUuid()).slice(0, 8), 16) % 1000000)).slice(-6); }\n\nfunction rateLimit_(key, max, windowSec) {\n  const c = CacheService.getScriptCache(), n = Number(c.get(key) || 0);\n  if (n >= max) throw appErr_('Terlalu banyak permintaan. Coba lagi beberapa menit lagi.', 'RATE');\n  c.put(key, String(n + 1), windowSec);\n}\n\nfunction withLock_(fn) {\n  const lock = LockService.getScriptLock();\n  try { lock.waitLock(15000); } catch (e) { throw appErr_('Server sedang sibuk, coba lagi.'); }\n  try { return fn(); } finally { lock.releaseLock(); }\n}"}, {"name": "Katalog.gs", "code": "/*  Katalog.gs — Tahap 1: username & profil, katalog game, tier, VP, leaderboard.\n *  Berkas ini melengkapi Kode.gs (satu proyek Apps Script yang sama). */\n\n// ───────── Username, gender, profil ─────────\nconst USERNAME_RESERVED_ = ['admin', 'administrator', 'kasir', 'cashier', 'gm', 'staff', 'owner', 'system', 'support'];\n\nfunction checkUsername_(v) {\n  const s = String(v == null ? '' : v).trim().replace(/^@/, '');\n  if (s.length < 3 || s.length > 20) return {ok: false, reason: 'Username 3–20 karakter'};\n  if (!/^[A-Za-z0-9._]+$/.test(s)) return {ok: false, reason: 'Hanya huruf, angka, titik, dan garis bawah'};\n  if (!/[A-Za-z]/.test(s)) return {ok: false, reason: 'Username harus memuat minimal satu huruf'};\n  if (USERNAME_RESERVED_.indexOf(s.toLowerCase()) >= 0) return {ok: false, reason: 'Username ini tidak boleh dipakai'};\n  return {ok: true, name: s, key: s.toLowerCase()};\n}\n\nfunction normUsername_(v) {\n  const r = checkUsername_(v);\n  if (!r.ok) throw appErr_(r.reason, 'BAD_USERNAME');\n  return {name: r.name, key: r.key};\n}\n\nfunction usernameTaken_(key, exceptUserId) {\n  const u = findOne_('Users', 'username_key', key);\n  return !!(u && String(u.user_id) !== String(exceptUserId || ''));\n}\n\nfunction normGender_(v) {\n  const s = String(v == null ? '' : v).trim().toUpperCase();\n  if (s === 'L' || s === 'LAKI-LAKI' || s === 'LAKI' || s === 'M') return 'L';\n  if (s === 'P' || s === 'PEREMPUAN' || s === 'F') return 'P';\n  throw appErr_('Pilih gender: Laki-laki atau Perempuan', 'BAD_GENDER');\n}\n\nfunction r_usernameCheck_(p) {\n  rateLimit_('UCHK', 300, 900);\n  const r = checkUsername_(p && p.username);\n  if (!r.ok) return {available: false, reason: r.reason};\n  if (usernameTaken_(r.key, p && p.exceptSelf)) return {available: false, reason: 'Username sudah dipakai'};\n  return {available: true, reason: ''};\n}\n\nfunction r_profileComplete_(p, u) {\n  return withLock_(function () {\n    const me = userById_(u.user_id);\n    if (!me) throw appErr_('Akun tidak ditemukan');\n    if (me.username && me.gender) throw appErr_('Profil sudah lengkap');\n    const name = clean_(p.name, 60);\n    if (!name) throw appErr_('Nama lengkap wajib diisi');\n    const un = normUsername_(p.username);\n    if (usernameTaken_(un.key, me.user_id)) throw appErr_('Username sudah dipakai. Pilih yang lain.', 'USERNAME_TAKEN');\n    const g = normGender_(p.gender);\n    updateRow_('Users', me._row, {name: name, username: un.name, username_key: un.key, gender: g, auto_created: ''});\n    touch_(me.user_id);\n    return {user: pubUser_(userById_(me.user_id))};\n  });\n}\n\n// ───────── Katalog game ─────────\nfunction gamePub_(g) {\n  return {\n    id: g.id || ('R' + g._row), name: g.name, image: g.image_url || '',\n    minPlayers: Number(g.min_players) || 1, maxPlayers: Number(g.max_players) || Number(g.min_players) || 1,\n    level: Number(g.level) || 0, duration: Number(g.duration) || 0,\n    mechanics: String(g.mechanics || '').split(',').map(function (x) { return x.trim(); }).filter(Boolean),\n    description: g.description || '', active: g.active !== 'N',\n    plays: Number(g.play_count) || 0, lastPlayed: g.last_played || ''\n  };\n}\n\nfunction r_gamesList_() {\n  const items = readAll_('Games').filter(function (g) { return g.name && g.active !== 'N'; }).map(gamePub_);\n  const mech = {};\n  items.forEach(function (g) { g.mechanics.forEach(function (m) { mech[m] = 1; }); });\n  items.sort(function (a, b) { return a.name.toLowerCase() < b.name.toLowerCase() ? -1 : 1; });\n  return {games: items, mechanics: Object.keys(mech).sort()};\n}\n\nfunction r_gamesAdmin_() {\n  return {games: readAll_('Games').filter(function (g) { return g.name; }).map(gamePub_)\n    .sort(function (a, b) { return a.name.toLowerCase() < b.name.toLowerCase() ? -1 : 1; })};\n}\n\nfunction r_gameSave_(p) {\n  const name = clean_(p.name, 80);\n  if (!name) throw appErr_('Nama game wajib diisi');\n  const minP = Math.round(Number(p.minPlayers)), maxP = Math.round(Number(p.maxPlayers));\n  if (!(minP >= 1 && minP <= 50) || !(maxP >= 1 && maxP <= 50)) throw appErr_('Jumlah pemain harus 1–50');\n  if (minP > maxP) throw appErr_('Pemain minimum tidak boleh lebih besar dari maksimum');\n  const level = Math.round((Number(p.level) || 0) * 10) / 10;\n  if (level < 0 || level > 5) throw appErr_('Level kesulitan 0–5');\n  const dur = Math.round(Number(p.duration) || 0);\n  if (dur < 5 || dur > 600) throw appErr_('Durasi 5–600 menit');\n  const mech = (Array.isArray(p.mechanics) ? p.mechanics : String(p.mechanics || '').split(','))\n    .map(function (x) { return clean_(x, 30); }).filter(Boolean);\n  const seen = {}, mechs = [];\n  mech.forEach(function (m) { if (!seen[m.toLowerCase()]) { seen[m.toLowerCase()] = 1; mechs.push(m); } });\n  if (mechs.length > 8) throw appErr_('Maksimal 8 mekanik');\n  const obj = {\n    name: name, image_url: normUrl_(p.image, true), min_players: String(minP), max_players: String(maxP),\n    level: String(level), duration: String(dur), mechanics: mechs.join(', '),\n    description: clean_(p.description, 300), active: p.active === false ? 'N' : 'Y'\n  };\n  return withLock_(function () {\n    const all = readAll_('Games');\n    const dup = all.some(function (g) {\n      return String(g.name).toLowerCase() === name.toLowerCase() && (!p.id || (g.id || ('R' + g._row)) !== String(p.id));\n    });\n    if (dup) throw appErr_('Nama game sudah ada');\n    if (p.id) {\n      const g = all.filter(function (x) { return (x.id || ('R' + x._row)) === String(p.id); })[0];\n      if (!g) throw appErr_('Game tidak ditemukan');\n      if (!g.id) obj.id = newId_('GAM');   // baris yang ditambah langsung di sheet diberi id\n      updateRow_('Games', g._row, obj);\n    } else {\n      obj.id = newId_('GAM'); obj.play_count = '0'; obj.last_played = ''; obj.created_at = nowStr_();\n      appendObj_('Games', obj);\n    }\n    return r_gamesAdmin_();\n  });\n}\n\nfunction r_gameDelete_(p) {\n  return withLock_(function () {\n    const g = readAll_('Games').filter(function (x) { return (x.id || ('R' + x._row)) === String(p.id); })[0];\n    if (!g) throw appErr_('Game tidak ditemukan');\n    if ((Number(g.play_count) || 0) > 0) throw appErr_('Game sudah pernah dimainkan, nonaktifkan saja (jangan dihapus).');\n    delRow_('Games', g._row);\n    return r_gamesAdmin_();\n  });\n}\n\n// ───────── Tier & VP ─────────\nfunction seedTiers_() {\n  if (readAll_('Tiers').length) return;\n  [['Novice', 0, '#9aa0a6'], ['Apprentice', 100, '#c08a4a'], ['Adept', 300, '#8fa3b8'], ['Veteran', 700, '#d4a72c'], ['Legend', 1500, '#7b5cd6']]\n    .forEach(function (t, i) {\n      appendObj_('Tiers', {id: newId_('TIR'), name: t[0], min_vp: String(t[1]), benefit: '', color: t[2], active: 'Y', sort: String(i), created_at: nowStr_()});\n    });\n}\n\nfunction tiersActive_() {\n  return readAll_('Tiers').filter(function (t) { return t.name && t.active !== 'N'; })\n    .sort(function (a, b) { return (Number(a.min_vp) || 0) - (Number(b.min_vp) || 0); });\n}\n\nfunction tierPub_(t) {\n  return {id: t.id || ('R' + t._row), name: t.name, minVp: Number(t.min_vp) || 0, benefit: t.benefit || '', color: t.color || '#9aa0a6', active: t.active !== 'N'};\n}\n\nfunction vpMonthNow_(u) {\n  const mk = fmt_(new Date(), 'yyyy-MM');\n  return String(u.vp_month_key) === mk ? (Number(u.vp_month) || 0) : 0;\n}\n\nfunction vpView_(u) {\n  const total = Number(u.vp_total) || 0, tiers = tiersActive_();\n  let cur = null, next = null;\n  tiers.forEach(function (t) { if ((Number(t.min_vp) || 0) <= total) cur = t; });\n  if (!cur && tiers.length) cur = tiers[0];\n  for (let i = 0; i < tiers.length; i++) if ((Number(tiers[i].min_vp) || 0) > total) { next = tiers[i]; break; }\n  let pct = 100;\n  if (next && cur) { const lo = Number(cur.min_vp) || 0, hi = Number(next.min_vp); pct = Math.max(0, Math.min(100, Math.round((total - lo) / Math.max(1, hi - lo) * 100))); }\n  return {\n    total: total, month: vpMonthNow_(u),\n    tier: cur ? {name: cur.name, color: cur.color || '#9aa0a6', benefit: cur.benefit || ''} : null,\n    next: next ? {name: next.name, minVp: Number(next.min_vp), remaining: Number(next.min_vp) - total} : null,\n    pct: pct\n  };\n}\n\nfunction r_tiersList_() { return {tiers: readAll_('Tiers').filter(function (t) { return t.name; }).map(tierPub_).sort(function (a, b) { return a.minVp - b.minVp; })}; }\n\nfunction r_tierSave_(p) {\n  const name = clean_(p.name, 30);\n  if (!name) throw appErr_('Nama tier wajib diisi');\n  const minVp = Math.round(Number(p.minVp));\n  if (!(minVp >= 0) || minVp > 10000000) throw appErr_('VP minimum tidak valid');\n  const color = /^#[0-9a-fA-F]{6}$/.test(String(p.color || '')) ? p.color : '#9aa0a6';\n  const active = p.active !== false;\n  return withLock_(function () {\n    const all = readAll_('Tiers').filter(function (t) { return t.name; });\n    const idOf = function (t) { return t.id || ('R' + t._row); };\n    const others = all.filter(function (t) { return !p.id || idOf(t) !== String(p.id); });\n    if (others.some(function (t) { return t.active !== 'N' && active && (Number(t.min_vp) || 0) === minVp; })) throw appErr_('Sudah ada tier lain dengan VP minimum yang sama');\n    const stillBase = others.some(function (t) { return t.active !== 'N' && (Number(t.min_vp) || 0) === 0; }) || (active && minVp === 0);\n    if (!stillBase) throw appErr_('Harus selalu ada satu tier aktif dengan VP minimum 0');\n    const obj = {name: name, min_vp: String(minVp), benefit: clean_(p.benefit, 200), color: color, active: active ? 'Y' : 'N'};\n    if (p.id) {\n      const t = all.filter(function (x) { return idOf(x) === String(p.id); })[0];\n      if (!t) throw appErr_('Tier tidak ditemukan');\n      if (!t.id) obj.id = newId_('TIR');\n      updateRow_('Tiers', t._row, obj);\n    } else {\n      obj.id = newId_('TIR'); obj.sort = String(all.length); obj.created_at = nowStr_();\n      appendObj_('Tiers', obj);\n    }\n    return r_tiersList_();\n  });\n}\n\nfunction r_tierDelete_(p) {\n  return withLock_(function () {\n    const all = readAll_('Tiers').filter(function (t) { return t.name; });\n    const idOf = function (t) { return t.id || ('R' + t._row); };\n    const t = all.filter(function (x) { return idOf(x) === String(p.id); })[0];\n    if (!t) throw appErr_('Tier tidak ditemukan');\n    const base = all.some(function (x) { return x !== t && x.active !== 'N' && (Number(x.min_vp) || 0) === 0; });\n    if (!base) throw appErr_('Harus selalu ada satu tier aktif dengan VP minimum 0');\n    delRow_('Tiers', t._row);\n    return r_tiersList_();\n  });\n}\n\nconst VP_SOURCES_ = {play_reguler: 'Main Reguler', play_party: 'Main Party Play', play_allday: 'All-Day Pass', event: 'Event', tournament: 'Turnamen', adjust: 'Penyesuaian admin'};\nfunction vpSourceLabel_(s) { return VP_SOURCES_[s] || 'VP'; }\n\n/* Harus dipanggil di dalam withLock_ (tidak membuat lock sendiri). */\nfunction awardVp_(u, amount, source, ref, note, by) {\n  amount = Math.round(Number(amount) || 0);\n  if (!amount) return 0;\n  const me = userById_(u.user_id);\n  if (!me) throw appErr_('Akun tidak ditemukan');\n  const cur = Number(me.vp_total) || 0, next = Math.max(0, cur + amount), delta = next - cur;\n  const tierBefore = (vpView_(me).tier || {}).name;\n  const mk = fmt_(new Date(), 'yyyy-MM');\n  const mBase = String(me.vp_month_key) === mk ? (Number(me.vp_month) || 0) : 0;\n  updateRow_('Users', me._row, {vp_total: String(next), vp_month: String(Math.max(0, mBase + delta)), vp_month_key: mk});\n  appendObj_('PointsLedger', {\n    id: newId_('VPL'), user_id: me.user_id, username: me.username || '', amount: String(delta), source: source || '', ref: ref || '',\n    note: clean_(note, 200), by_user: by ? by.user_id : '', by_name: by ? (by.name || '') : '', ts: nowStr_()\n  });\n  touch_(me.user_id);\n  const c = CacheService.getScriptCache();\n  c.remove('LB_all'); c.remove('LB_month');\n  const after = userById_(me.user_id), tierAfter = (vpView_(after).tier || {}).name;\n  if (delta > 0 && tierAfter && tierAfter !== tierBefore) { feedAdd_('tier', after.username, after.username + ' naik tier ke ' + tierAfter); }\n  if (delta > 0) checkBadges_(after);\n  return delta;\n}\n\nfunction r_vpAdjust_(p, staff) {\n  const amount = Math.round(Number(p.amount));\n  if (!amount || Math.abs(amount) > 100000) throw appErr_('Jumlah VP tidak valid (maks ±100.000)');\n  const note = clean_(p.note, 200);\n  if (!note) throw appErr_('Catatan wajib diisi');\n  return withLock_(function () {\n    const u = userById_(p.userId);\n    if (!u) throw appErr_('Pelanggan tidak ditemukan');\n    awardVp_(u, amount, 'adjust', '', note, staff);\n    const fresh = userById_(u.user_id);\n    return {vp: vpView_(fresh), name: fresh.name, username: fresh.username || ''};\n  });\n}\n\n// ───────── Leaderboard ─────────\nfunction lbBuild_(board) {\n  const mk = fmt_(new Date(), 'yyyy-MM');\n  const rows = [];\n  readAll_('Users').forEach(function (u) {\n    if (u.role !== 'customer' || u.active === 'N' || !u.username) return;\n    const vp = board === 'month' ? (String(u.vp_month_key) === mk ? (Number(u.vp_month) || 0) : 0) : (Number(u.vp_total) || 0);\n    if (vp > 0) rows.push({uid: u.user_id, username: u.username, vp: vp});\n  });\n  rows.sort(function (a, b) { return b.vp - a.vp || (a.username.toLowerCase() < b.username.toLowerCase() ? -1 : 1); });\n  return rows;\n}\n\nfunction r_leaderboard_(p, u) {\n  const board = p && p.board === 'month' ? 'month' : 'all';\n  const limit = p && Number(p.limit) > 10 ? 50 : 10;\n  const key = 'LB_' + board, c = CacheService.getScriptCache();\n  let rows = null;\n  const hit = c.get(key);\n  if (hit) { try { rows = JSON.parse(hit); } catch (e) { rows = null; } }\n  if (!rows) {\n    rows = lbBuild_(board);\n    try { c.put(key, JSON.stringify(rows), 60); } catch (e) {}\n  }\n  // peringkat dengan skor sama = peringkat sama\n  const ranked = []; let last = null, rank = 0;\n  rows.forEach(function (r, i) { if (r.vp !== last) { rank = i + 1; last = r.vp; } ranked.push({rank: rank, r: r}); });\n  const items = ranked.slice(0, limit).map(function (x) {\n    return {rank: x.rank, username: x.r.username, vp: x.r.vp, me: x.r.uid === u.user_id};\n  });\n  const mine = ranked.filter(function (x) { return x.r.uid === u.user_id; })[0];\n  return {board: board, items: items, total: rows.length, me: mine ? {rank: mine.rank, vp: mine.r.vp} : null};\n}\n"}, {"name": "Visits.gs", "code": "/*  Visits.gs — Tahap 2: Party Play (grup), kunjungan di kasir, pencatatan game.  */\n\nconst PARTY_MIN = 4, PARTY_MAX = 15, WAIT_MS = 30 * 86400000;\nconst monthKey_ = function () { return fmt_(new Date(), 'yyyy-MM'); };\nconst quorumFor_ = function (n) { return Math.floor(n / 2) + 1; };\n\n// ───────── helper grup ─────────\n/* Cari pelanggan lewat username ATAU nomor WhatsApp. */\nfunction findCustomerByHandle_(q) {\n  q = String(q == null ? '' : q).trim();\n  if (!q) return null;\n  const u = /^\\+?[\\d\\s-]{8,}$/.test(q) ? userByPhone_(normPhone_(q)) : findOne_('Users', 'username_key', q.replace(/^@/, '').toLowerCase());\n  return u && u.role === 'customer' ? u : null;\n}\nfunction gmActive_(gid) { return readAll_('GroupMembers').filter(function (m) { return m.group_id === gid && m.status === 'active'; }); }\nfunction gmOfUser_(uid) { return readAll_('GroupMembers').filter(function (m) { return m.user_id === uid && m.status === 'active'; })[0] || null; }\nfunction groupById_(id) { return findOne_('Groups', 'id', id); }\nfunction kidsOf_(guardianId) { return readAll_('Kids').filter(function (k) { return k.guardian_id === guardianId && k.active !== 'N'; }); }\nfunction usersMap_() { const m = {}; readAll_('Users').forEach(function (u) { m[u.user_id] = u; }); return m; }\n\nfunction memberLabels_(members, staffView) {\n  const um = usersMap_(), km = {};\n  readAll_('Kids').forEach(function (k) { km[k.id] = k; });\n  return members.map(function (m) {\n    if (m.user_id) {\n      const u = um[m.user_id] || {};\n      return {id: m.id, userId: m.user_id, isKid: false, label: u.username || u.name || '?', fullName: staffView ? u.name : undefined, joined: m.joined_at};\n    }\n    const k = km[m.kid_id] || {};\n    const g = um[k.guardian_id] || {};\n    return {id: m.id, kidId: m.kid_id, guardianId: k.guardian_id, isKid: true, label: 'Anak: ' + (k.name || '?'), fullName: staffView ? (k.name + ' (wali: ' + (g.name || '?') + ')') : undefined, joined: m.joined_at};\n  });\n}\n\nfunction dissolveGroup_(g, freeQuota) {\n  gmActive_(g.id).forEach(function (m) {\n    updateRow_('GroupMembers', m._row, {status: 'left', left_at: nowStr_()});\n    if (m.user_id && freeQuota) { const u = userById_(m.user_id); if (u) { updateRow_('Users', u._row, {grp_change_key: '', grp_change_ts: ''}); touch_(u.user_id); } }\n  });\n  updateRow_('Groups', g._row, {status: 'dissolved'});\n}\n\n/* Hitung ulang status grup; bubarkan bila kosong / kehabisan waktu menunggu. */\nfunction refreshGroup_(g) {\n  if (g.status === 'dissolved') return g;\n  const mem = gmActive_(g.id);\n  if (!mem.length) { updateRow_('Groups', g._row, {status: 'dissolved'}); return groupById_(g.id); }\n  if (mem.length >= PARTY_MIN) {\n    if (g.status !== 'active' || g.waiting_since) updateRow_('Groups', g._row, {status: 'active', waiting_since: ''});\n  } else {\n    const since = Number(g.waiting_since) || 0;\n    if (g.status !== 'waiting' || !since) updateRow_('Groups', g._row, {status: 'waiting', waiting_since: String(Date.now())});\n    else if (Date.now() - since > WAIT_MS) { dissolveGroup_(g, true); }\n  }\n  return groupById_(g.id);\n}\n\n/* Keluarkan satu anggota akun (beserta anak walinya); pindahkan ketua bila perlu. */\nfunction detachUser_(g, uid) {\n  readAll_('GroupMembers').filter(function (m) { return m.group_id === g.id && m.status === 'active'; }).forEach(function (m) {\n    let mine = m.user_id === uid;\n    if (m.kid_id) { const k = readAll_('Kids').filter(function (x) { return x.id === m.kid_id; })[0]; mine = !!(k && k.guardian_id === uid); }\n    if (mine) updateRow_('GroupMembers', m._row, {status: 'left', left_at: nowStr_()});\n  });\n  if (g.leader_id === uid) {\n    const next = gmActive_(g.id).filter(function (m) { return m.user_id; }).sort(function (a, b) { return String(a.joined_at) < String(b.joined_at) ? -1 : 1; })[0];\n    if (next) updateRow_('Groups', g._row, {leader_id: next.user_id});\n    else gmActive_(g.id).forEach(function (m) { updateRow_('GroupMembers', m._row, {status: 'left', left_at: nowStr_()}); });\n  }\n  return refreshGroup_(groupById_(g.id));\n}\n\n/* Kuota perubahan Party: bawaan reset tiap tanggal 1 (zona WITA). Bila admin mengisi party_cooldown_days > 0, jeda dihitung dari perubahan terakhir. */\nconst WITA_MS = 8 * 3600000;\nfunction quotaInfo_(u) { return quotaCalc_(u.grp_change_key, u.grp_change_ts); }\nfunction quotaCalc_(keyVal, tsVal) {\n  const days = Number(settings_().party_cooldown_days) || 0, now = Date.now();\n  let until = 0;\n  if (days > 0) { const t = Number(tsVal) || 0; if (t) until = t + days * 86400000; }\n  else if (String(keyVal) === monthKey_()) { const a = monthKey_().split('-'); until = Date.UTC(Number(a[0]), Number(a[1]), 1) - WITA_MS; }\n  if (!until || until <= now) return {can: true, daysLeft: 0, until: '', mode: days > 0 ? 'days' : 'month'};\n  return {can: false, daysLeft: Math.max(1, Math.ceil((until - now) / 86400000)), until: fmt_(new Date(until), 'yyyy-MM-dd'), mode: days > 0 ? 'days' : 'month'};\n}\nfunction needQuota_(u) {\n  const q = quotaInfo_(u);\n  if (!q.can) throw appErr_('Perubahan anggota Party sedang dibatasi. Bisa lagi dalam ' + q.daysLeft + ' hari (' + q.until + ').', 'GROUP_QUOTA');\n}\n/* Ganti nama grup punya hitungan sendiri per grup, dengan jadwal reset yang sama. */\nfunction renameQuota_(g) { return quotaCalc_(g.rename_key, g.rename_ts); }\nfunction useQuota_(uid) { const u = userById_(uid); updateRow_('Users', u._row, {grp_change_key: monthKey_(), grp_change_ts: String(Date.now())}); touch_(uid); }\n\n/* Admin: daftar pelanggan yang sedang kena jeda, dan reset jeda (satu orang / semua). */\nfunction r_partyQuotaList_() {\n  const um = readAll_('Users');\n  const lead = {};\n  readAll_('Groups').forEach(function (g) { if (g.status !== 'dissolved') lead[g.leader_id] = g; });\n  const list = um.filter(function (u) { return u.role === 'customer'; }).map(function (u) {\n    const a = quotaInfo_(u), b = lead[u.user_id] ? renameQuota_(lead[u.user_id]) : {can: true, daysLeft: 0, until: ''};\n    return {u: u, a: a, b: b};\n  }).filter(function (x) { return !x.a.can || !x.b.can; })\n    .map(function (x) { return {id: x.u.user_id, username: x.u.username || x.u.name, daysLeft: Math.max(x.a.daysLeft, x.b.daysLeft), until: x.a.daysLeft >= x.b.daysLeft ? x.a.until : x.b.until,\n      member: !x.a.can, rename: !x.b.can}; });\n  const days = Number(settings_().party_cooldown_days) || 0;\n  return {list: list.slice(0, 100), mode: days > 0 ? 'days' : 'month', days: days};\n}\nfunction r_partyQuotaReset_(p, admin) {\n  return withLock_(function () {\n    const targets = p.all ? readAll_('Users').filter(function (u) { return u.role === 'customer'; }) : [userById_(String(p.userId))].filter(Boolean);\n    targets.forEach(function (u) { if (u.grp_change_key || u.grp_change_ts) updateRow_('Users', u._row, {grp_change_key: '', grp_change_ts: ''}); });\n    readAll_('Groups').forEach(function (g) {\n      if ((g.rename_key || g.rename_ts) && (p.all || targets.some(function (u) { return u.user_id === g.leader_id; }))) updateRow_('Groups', g._row, {rename_key: '', rename_ts: ''});\n    });\n    if (targets.length) { pingMany_(targets.map(function (u) { return u.user_id; })); }\n    return r_partyQuotaList_();\n  });\n}\n\nfunction groupView_(g, me) {\n  const mem = gmActive_(g.id), labels = memberLabels_(mem, false), n = mem.length;\n  const first = g.first_done !== 'Y';\n  const since = Number(g.waiting_since) || 0;\n  return {\n    id: g.id, name: g.name, status: g.status, n: n, isLeader: g.leader_id === me.user_id, leaderId: g.leader_id,\n    members: labels.map(function (m) { return {id: m.id, label: m.label, isKid: m.isKid, isMe: m.userId === me.user_id, isLeader: m.userId === g.leader_id, mine: m.isKid ? m.guardianId === me.user_id : m.userId === me.user_id}; }),\n    pendingRename: (pendingRename_(g.id) || {}).new_name || '', renameQuota: renameQuota_(g),\n    firstVisit: first, required: n >= PARTY_MIN ? (first ? n : quorumFor_(n)) : null,\n    daysLeft: g.status === 'waiting' && since ? Math.max(0, Math.ceil((since + WAIT_MS - Date.now()) / 86400000)) : null\n  };\n}\n\n// ───────── rute pelanggan ─────────\nfunction r_groupMy_(p, u) { return withLock_(function () { return groupMyCore_(p, u); }); }\nfunction groupMyCore_(p, u) {\n  {\n    let m = gmOfUser_(u.user_id), g = m ? groupById_(m.group_id) : null;\n    if (g) { g = refreshGroup_(g); m = gmOfUser_(u.user_id); if (!m) g = null; }\n    const gnames = {};\n    const invites = readAll_('GroupMembers').filter(function (x) { return x.user_id === u.user_id && x.status === 'invited'; }).map(function (x) {\n      const gg = groupById_(x.group_id), by = userById_(x.invited_by) || {};\n      return gg && gg.status !== 'dissolved' ? {id: x.id, group: gg.name, from: by.username || ''} : null;\n    }).filter(Boolean);\n    const me = userById_(u.user_id);\n    return {group: g && g.status !== 'dissolved' ? groupView_(g, u) : null, invites: invites, canChange: quotaInfo_(me).can, quota: quotaInfo_(me),\n      kids: kidsOf_(u.user_id).map(function (k) { return {id: k.id, name: k.name}; }), rules: {min: PARTY_MIN, max: PARTY_MAX}};\n  }\n}\n\nfunction r_groupCreate_(p, u) {\n  const name = clean_(p.name, 40);\n  if (!name) throw appErr_('Nama grup wajib diisi');\n  return withLock_(function () {\n    const me = userById_(u.user_id);\n    if (!me.username) throw appErr_('Lengkapi profil dulu');\n    if (gmOfUser_(me.user_id)) throw appErr_('Kamu sudah tergabung di sebuah grup');\n    needQuota_(me);\n    const dup = readAll_('Groups').some(function (g) { return g.status !== 'dissolved' && g.name.toLowerCase() === name.toLowerCase(); });\n    if (dup) throw appErr_('Nama grup sudah dipakai');\n    const gid = newId_('PTY');\n    appendObj_('Groups', {id: gid, name: name, leader_id: me.user_id, status: 'waiting', first_done: 'N', waiting_since: String(Date.now()), created_at: nowStr_()});\n    appendObj_('GroupMembers', {id: newId_('MBR'), group_id: gid, user_id: me.user_id, status: 'active', joined_at: nowStr_()});\n    useQuota_(me.user_id);\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupInvite_(p, u) {\n  return withLock_(function () {\n    const m = gmOfUser_(u.user_id), g = m ? groupById_(m.group_id) : null;\n    if (!g || g.status === 'dissolved') throw appErr_('Kamu belum punya grup');\n    if (g.leader_id !== u.user_id) throw appErr_('Hanya ketua yang bisa mengundang');\n    rateLimit_('INV_' + u.user_id, 30, 3600);   // cegah menebak-nebak nomor\n    let t = findCustomerByHandle_(p.username);\n    const qh = String(p.username == null ? '' : p.username).trim();\n    let createdNew = false;\n    if (!t && /^\\+?[\\d\\s-]{8,}$/.test(qh)) {\n      const phone = normPhone_(qh);\n      if (!userByPhone_(phone)) {\n        // nomor belum terdaftar: cek WhatsApp, lalu buat akun otomatis dari nama yang diisi ketua\n        waCheck_(phone, u.user_id, !!p.recheck);\n        const nm = clean_(p.newName, 60);\n        if (!nm) return {needName: true, phone: phone, masked: maskPhone_(phone)};\n        t = createUser_(phone, nm, '', {username: autoUsername_(nm), auto: true});\n        createdNew = true;\n      }\n    }\n    if (!t || t.active === 'N') throw appErr_('Pelanggan tidak ditemukan. Cek username atau nomor WhatsApp-nya.');\n    if (t.user_id === u.user_id) throw appErr_('Itu akun kamu sendiri');\n    const all = readAll_('GroupMembers');\n    if (all.some(function (x) { return x.group_id === g.id && x.user_id === t.user_id && (x.status === 'active' || x.status === 'invited'); })) throw appErr_('Sudah menjadi anggota atau sudah diundang');\n    if (all.filter(function (x) { return x.group_id === g.id && x.status === 'invited'; }).length >= 20) throw appErr_('Terlalu banyak undangan tertunda');\n    appendObj_('GroupMembers', {id: newId_('MBR'), group_id: g.id, user_id: t.user_id, status: 'invited', invited_by: u.user_id});\n    touch_(t.user_id);\n    if (createdNew) {\n      try { sendWhatsApp_(t.phone, 'Halo ' + t.name + ', kamu diundang ' + (userById_(u.user_id).username || 'temanmu') + ' ke Party \"' + g.name + '\" di ' + settings_().cafe_name + '. Buka ' + (prop_('URL') || 'aplikasinya') + ' dan masuk dengan nomor WhatsApp ini untuk menerima undangan.'); } catch (e) { /* undangan tetap tersimpan */ }\n    }\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupRespond_(p, u) {\n  return withLock_(function () {\n    const inv = readAll_('GroupMembers').filter(function (x) { return x.id === String(p.inviteId) && x.user_id === u.user_id && x.status === 'invited'; })[0];\n    if (!inv) throw appErr_('Undangan tidak ditemukan');\n    if (!p.accept) { updateRow_('GroupMembers', inv._row, {status: 'declined'}); return groupMyCore_(p, u); }\n    let g = groupById_(inv.group_id);\n    if (!g || g.status === 'dissolved') { updateRow_('GroupMembers', inv._row, {status: 'declined'}); throw appErr_('Grup sudah tidak ada'); }\n    const me = userById_(u.user_id);\n    needQuota_(me);\n    const cur = gmOfUser_(me.user_id), myKids = kidsOf_(me.user_id);\n    const oldG = cur ? groupById_(cur.group_id) : null;\n    const add = 1 + (oldG ? myKids.filter(function (k) { return gmActive_(oldG.id).some(function (x) { return x.kid_id === k.id; }); }).length : 0);\n    if (gmActive_(g.id).length + add > PARTY_MAX) throw appErr_('Grup sudah penuh (maks ' + PARTY_MAX + ' anggota)');\n    // pindah grup = keluar dari grup lama + gabung baru, dihitung 1 perubahan\n    const kidIds = [];\n    if (oldG) {\n      gmActive_(oldG.id).forEach(function (x) { if (x.kid_id && myKids.some(function (k) { return k.id === x.kid_id; })) kidIds.push(x.kid_id); });\n      detachUser_(oldG, me.user_id);\n    }\n    updateRow_('GroupMembers', inv._row, {status: 'active', joined_at: nowStr_()});\n    kidIds.forEach(function (kid) { appendObj_('GroupMembers', {id: newId_('MBR'), group_id: g.id, kid_id: kid, status: 'active', joined_at: nowStr_()}); });\n    refreshGroup_(groupById_(g.id));\n    useQuota_(me.user_id);\n    // undangan lain yang masih tertunda tetap berlaku\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupLeave_(p, u) {\n  return withLock_(function () {\n    const m = gmOfUser_(u.user_id), g = m ? groupById_(m.group_id) : null;\n    if (!g) throw appErr_('Kamu tidak sedang di grup');\n    const me = userById_(u.user_id);\n    needQuota_(me);\n    detachUser_(g, me.user_id);\n    useQuota_(me.user_id);\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupKidAdd_(p, u) {\n  const name = clean_(p.name, 40);\n  if (!name) throw appErr_('Nama anak wajib diisi');\n  return withLock_(function () {\n    const m = gmOfUser_(u.user_id), g = m ? groupById_(m.group_id) : null;\n    if (!g) throw appErr_('Gabung atau buat grup dulu');\n    if (gmActive_(g.id).length >= PARTY_MAX) throw appErr_('Grup sudah penuh (maks ' + PARTY_MAX + ' anggota)');\n    if (kidsOf_(u.user_id).some(function (k) { return k.name.toLowerCase() === name.toLowerCase(); })) throw appErr_('Nama anak sudah terdaftar');\n    const kid = newId_('KID');\n    appendObj_('Kids', {id: kid, name: name, guardian_id: u.user_id, active: 'Y', created_at: nowStr_()});\n    appendObj_('GroupMembers', {id: newId_('MBR'), group_id: g.id, kid_id: kid, status: 'active', joined_at: nowStr_()});\n    refreshGroup_(groupById_(g.id));\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupKidRemove_(p, u) {\n  return withLock_(function () {\n    const k = readAll_('Kids').filter(function (x) { return x.id === String(p.kidId) && x.guardian_id === u.user_id; })[0];\n    if (!k) throw appErr_('Data anak tidak ditemukan');\n    readAll_('GroupMembers').filter(function (m) { return m.kid_id === k.id && m.status === 'active'; }).forEach(function (m) {\n      updateRow_('GroupMembers', m._row, {status: 'left', left_at: nowStr_()});\n      const g = groupById_(m.group_id); if (g) refreshGroup_(g);\n    });\n    updateRow_('Kids', k._row, {active: 'N'});\n    return groupMyCore_(p, u);\n  });\n}\n\n// ───────── rute kasir ─────────\nfunction r_groupsFind_(p) {\n  const q = String(p.q || '').trim().toLowerCase();\n  if (!q) throw appErr_('Ketik nama grup atau username anggota');\n  const um = usersMap_(), all = readAll_('GroupMembers').filter(function (m) { return m.status === 'active'; });\n  const out = [];\n  readAll_('Groups').forEach(function (g) {\n    if (g.status === 'dissolved' || out.length >= 15) return;\n    const mem = all.filter(function (m) { return m.group_id === g.id; });\n    const hit = g.name.toLowerCase().indexOf(q) >= 0 || mem.some(function (m) { const u = um[m.user_id]; return u && (String(u.username_key).indexOf(q) >= 0 || String(u.name).toLowerCase().indexOf(q) >= 0); });\n    if (hit) out.push({id: g.id, name: g.name, status: g.status, n: mem.length, leader: (um[g.leader_id] || {}).username || ''});\n  });\n  return {groups: out};\n}\n\nfunction r_groupStaffView_(p) {\n  return withLock_(function () {\n    let g = groupById_(String(p.groupId));\n    if (!g || g.status === 'dissolved') throw appErr_('Grup tidak ditemukan');\n    g = refreshGroup_(g);\n    if (g.status === 'dissolved') throw appErr_('Grup sudah bubar');\n    const mem = gmActive_(g.id), n = mem.length, first = g.first_done !== 'Y';\n    const today = fmt_(new Date(), 'yyyy-MM-dd'), vs = tail_('Visits', 600).filter(function (v) { return v.date === today; });\n    return {id: g.id, name: g.name, status: g.status, n: n, firstVisit: first, required: n >= PARTY_MIN ? (first ? n : quorumFor_(n)) : null,\n      daysLeft: g.status === 'waiting' ? Math.max(0, Math.ceil(((Number(g.waiting_since) || Date.now()) + WAIT_MS - Date.now()) / 86400000)) : null,\n      members: memberLabels_(mem, true).map(function (m) {\n        return {id: m.id, label: m.label, fullName: m.fullName, isKid: m.isKid, leader: m.userId === g.leader_id,\n          doneToday: vs.some(function (v) { return m.isKid ? v.kid_id === m.kidId : v.user_id === m.userId; })};\n      })};\n  });\n}\n\nfunction r_visitMeta_() {\n  const s = settings_();\n  const camps = readAll_('Campaigns').filter(function (c) { return c.active !== 'N' && campState_(c).running; }).map(function (c) { return {id: c.id, name: c.name, icon: c.icon}; });\n  return {campaigns: camps, vp: {reguler: s.vp_play_reguler, party: s.vp_play_party, allday: s.vp_play_allday, hourReguler: s.vp_hour_reguler, hourParty: s.vp_hour_party}};\n}\n\nconst VISIT_LABEL_ = {reguler: 'Main Reguler', party: 'Main Party Play', allday: 'All-Day Pass'};\n\n/* Catat satu kunjungan. Dipanggil dalam lock. Mengembalikan ringkasan untuk kasir. */\nfunction recordVisit_(who, type, hours, gid, staff, campaignId, s, allowDup) {\n  const u = who.user || null, date = fmt_(new Date(), 'yyyy-MM-dd');\n  const res = {label: who.label, vp: 0, stamp: false, stampMsg: '', dup: false};\n  // pengaman salah ketuk: orang yang sama dicatat lagi dalam 10 menit terakhir ditahan, kecuali kasir menyetujui\n  const cutoff = fmt_(new Date(Date.now() - 10 * 60000), 'yyyy-MM-dd HH:mm:ss');\n  const dup = tail_('Visits', 300).some(function (v) { return String(v.ts) >= cutoff && (u ? v.user_id === u.user_id : v.kid_id === who.kidId); });\n  if (dup && !allowDup) { res.dup = true; return res; }\n  const vid = newId_('VST');\n  if (u) {\n    const extra = type === 'allday' ? 0 : (Number(s['vp_hour_' + type]) || 0) * Math.max(0, Math.floor(hours) - 2);\n    const vp = (Number(s['vp_play_' + type]) || 0) + extra;\n    if (vp > 0) res.vp = awardVp_(u, vp, 'play_' + type, vid, VISIT_LABEL_[type] + (type === 'allday' ? '' : ' ' + hours + ' jam'), staff);\n    const qualifies = type === 'allday' || (type === 'party' && hours >= 3) || (type === 'reguler' && hours >= 2);\n    if (qualifies) {\n      if (!campaignId) res.stampMsg = 'Pilih event stamp untuk memberi stamp';\n      else {\n        try { const sr = stampCore_({userId: u.user_id, campaignId: campaignId, qty: 1, note: VISIT_LABEL_[type], skipCooldown: true}, staff, s); res.stamp = true; notifyRewardIfReady_(sr.customer, u); notifyNearIfReady_(sr.customer, u); }\n        catch (e) { res.stampMsg = e.message || 'Stamp gagal'; }\n      }\n    }\n  }\n  appendObj_('Visits', {id: vid, date: date, ts: nowStr_(), user_id: u ? u.user_id : '', kid_id: u ? '' : who.kidId, type: type, hours: String(hours),\n    group_id: gid || '', by_user: staff.user_id, by_name: staff.name, stamp: res.stamp ? 'Y' : 'N', vp: String(res.vp)});\n  if (u) { checkBadges_(userById_(u.user_id)); touch_(u.user_id); }\n  return res;\n}\n\nfunction checkHours_(h, type) {\n  if (type === 'allday') return 0;\n  h = Number(h);\n  if (!(h >= 0.5 && h <= 24)) throw appErr_('Durasi main 0,5–24 jam');\n  return Math.round(h * 2) / 2;\n}\n\nfunction r_visitParty_(p, staff) {\n  const s = settings_();\n  return withLock_(function () {\n    let g = groupById_(String(p.groupId));\n    if (!g || g.status === 'dissolved') throw appErr_('Grup tidak ditemukan');\n    g = refreshGroup_(g);\n    if (g.status === 'dissolved') throw appErr_('Grup sudah bubar');\n    const hours = checkHours_(p.hours, 'party');\n    const mem = gmActive_(g.id), n = mem.length, ids = Array.isArray(p.presentIds) ? p.presentIds.map(String) : [];\n    const present = mem.filter(function (m) { return ids.indexOf(m.id) >= 0; });\n    if (!present.length) throw appErr_('Pilih minimal satu anggota yang hadir');\n    const first = g.first_done !== 'Y', required = n >= PARTY_MIN ? (first ? n : quorumFor_(n)) : null;\n    const accounts = present.filter(function (m) { return m.user_id; }).length;\n    const met = g.status === 'active' && required !== null && present.length >= required && accounts >= 1;\n    const type = met ? 'party' : 'reguler';\n    const labels = memberLabels_(present, true), um = usersMap_(), km = {};\n    readAll_('Kids').forEach(function (k) { km[k.id] = k; });\n    const only = Array.isArray(p.onlyIds) ? p.onlyIds.map(String) : null;   // ulangi hanya untuk anggota tertentu (kuorum tetap dihitung dari semua yang hadir)\n    const results = [];\n    present.forEach(function (m, i) {\n      if (only && only.indexOf(m.id) < 0) return;\n      const who = m.user_id ? {user: um[m.user_id], label: labels[i].label} : {kidId: m.kid_id, label: labels[i].label};\n      const r = recordVisit_(who, type, hours, g.id, staff, p.campaignId, s, !!p.allowDup);\n      r.memberId = m.id; results.push(r);\n    });\n    if (met && first && results.some(function (r) { return !r.dup; })) updateRow_('Groups', g._row, {first_done: 'Y'});\n    return {quorumMet: met, type: type, present: present.length, required: required, n: n, results: results};\n  });\n}\n\nfunction r_visitSingle_(p, staff) {\n  const s = settings_(), type = p.type === 'allday' ? 'allday' : 'reguler';\n  return withLock_(function () {\n    const u = p.userId ? userById_(String(p.userId)) : resolveCustomer_(p.q);\n    if (!u || u.role !== 'customer') throw appErr_('Pelanggan tidak ditemukan');\n    if (u.active === 'N') throw appErr_('Akun tidak aktif');\n    const hours = checkHours_(p.hours, type);\n    const r = recordVisit_({user: u, label: u.username || u.name}, type, hours, '', staff, p.campaignId, s, !!p.allowDup);\n    r.customer = custView_(userById_(u.user_id));\n    return {type: type, results: [r], customer: r.customer};\n  });\n}\n\n/* Kunjungan massal (rombongan non-Party): jenis & durasi sama untuk semua, maks 20 orang. */\nfunction r_visitBatch_(p, staff) {\n  const s = settings_(), type = p.type === 'allday' ? 'allday' : 'reguler';\n  const items = Array.isArray(p.items) ? p.items : [];\n  if (!items.length) throw appErr_('Belum ada pelanggan');\n  if (items.length > 20) throw appErr_('Maksimal 20 orang sekaligus');\n  const hours = checkHours_(p.hours, type);\n  return withLock_(function () {\n    const results = items.map(function (it) {\n      try {\n        const u = userById_(String(it.userId));\n        if (!u || u.role !== 'customer' || u.active === 'N') throw appErr_('Pelanggan tidak ditemukan');\n        const r = recordVisit_({user: u, label: u.username || u.name}, type, hours, '', staff, p.campaignId, s, !!p.allowDup);\n        r.userId = u.user_id; r.ok = !r.dup; r.customer = custView_(userById_(u.user_id));\n        if (r.dup) r.error = 'Baru dicatat <10 menit lalu';\n        return r;\n      } catch (e) { return {userId: String(it.userId), ok: false, error: e.message || 'Gagal'}; }\n    });\n    return {type: type, results: results};\n  });\n}\n\n// ───────── catat game yang dimainkan (kasir / GM / admin) ─────────\nfunction r_gamePlay_(p, staff) {\n  return withLock_(function () {\n    const g = readAll_('Games').filter(function (x) { return (x.id || ('R' + x._row)) === String(p.gameId); })[0];\n    if (!g) throw appErr_('Game tidak ditemukan');\n    const names = Array.isArray(p.usernames) ? p.usernames : [];\n    const ids = [];\n    names.forEach(function (n) {\n      const key = String(n || '').trim().replace(/^@/, '').toLowerCase();\n      if (!key) return;\n      const u = findOne_('Users', 'username_key', key);\n      if (!u) throw appErr_('Username \"' + n + '\" tidak ditemukan');\n      if (ids.indexOf(u.user_id) < 0) ids.push(u.user_id);\n    });\n    appendObj_('VisitGames', {id: newId_('VGM'), game_id: g.id || ('R' + g._row), game_name: g.name, players: ids.join(','), group_id: clean_(p.groupId, 30), by_user: staff.user_id, by_name: staff.name, ts: nowStr_()});\n    ids.forEach(function (id) { checkBadges_(userById_(id)); });\n    const patch = {play_count: String((Number(g.play_count) || 0) + 1), last_played: nowStr_()};\n    if (!g.id) patch.id = newId_('GAM');\n    updateRow_('Games', g._row, patch);\n    return {name: g.name, plays: Number(patch.play_count)};\n  });\n}\n\n\n// ───────── ganti nama grup (butuh persetujuan admin) ─────────\nfunction pendingRename_(gid) { return readAll_('GroupRenames').filter(function (r) { return r.group_id === gid && r.status === 'pending'; })[0] || null; }\nfunction groupNameTaken_(name, exceptId) {\n  return readAll_('Groups').some(function (g) { return g.status !== 'dissolved' && g.id !== exceptId && g.name.toLowerCase() === name.toLowerCase(); });\n}\n\nfunction r_groupRenameRequest_(p, u) {\n  const name = clean_(p.name, 40);\n  if (!name) throw appErr_('Nama baru wajib diisi');\n  return withLock_(function () {\n    const m = gmOfUser_(u.user_id), g = m ? groupById_(m.group_id) : null;\n    if (!g || g.status === 'dissolved') throw appErr_('Kamu belum punya grup');\n    if (g.leader_id !== u.user_id) throw appErr_('Hanya ketua yang bisa mengajukan ganti nama');\n    if (name.toLowerCase() === g.name.toLowerCase()) throw appErr_('Nama baru sama dengan nama sekarang');\n    if (groupNameTaken_(name, g.id)) throw appErr_('Nama grup sudah dipakai');\n    if (pendingRename_(g.id)) throw appErr_('Masih ada pengajuan yang menunggu admin. Batalkan dulu untuk mengganti.');\n    const rq = renameQuota_(g);\n    if (!rq.can) throw appErr_('Nama grup baru bisa diganti lagi dalam ' + rq.daysLeft + ' hari (' + rq.until + ').', 'GROUP_QUOTA');\n    appendObj_('GroupRenames', {id: newId_('REN'), group_id: g.id, requester_id: u.user_id, old_name: g.name, new_name: name, status: 'pending', ts: nowStr_()});\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_groupRenameCancel_(p, u) {\n  return withLock_(function () {\n    const m = gmOfUser_(u.user_id), req = m ? pendingRename_(m.group_id) : null;\n    if (!req || req.requester_id !== u.user_id) throw appErr_('Tidak ada pengajuan untuk dibatalkan');\n    updateRow_('GroupRenames', req._row, {status: 'cancelled', decided_at: nowStr_()});\n    return groupMyCore_(p, u);\n  });\n}\n\nfunction r_renamesList_() {\n  const um = usersMap_(), all = readAll_('GroupRenames').filter(function (r) { return r.id; });\n  const pub = function (r) { return {id: r.id, groupId: r.group_id, oldName: r.old_name, newName: r.new_name, status: r.status, note: r.note || '', ts: r.ts, by: (um[r.requester_id] || {}).username || ''}; };\n  return {pending: all.filter(function (r) { return r.status === 'pending'; }).map(pub),\n          recent: all.filter(function (r) { return r.status === 'approved' || r.status === 'rejected'; }).slice(-10).reverse().map(pub)};\n}\n\nfunction r_renameDecide_(p, staff) {\n  return withLock_(function () {\n    const req = readAll_('GroupRenames').filter(function (r) { return r.id === String(p.id) && r.status === 'pending'; })[0];\n    if (!req) throw appErr_('Pengajuan tidak ditemukan atau sudah diproses');\n    const g = groupById_(req.group_id), note = clean_(p.note, 120);\n    if (!g || g.status === 'dissolved') {\n      updateRow_('GroupRenames', req._row, {status: 'cancelled', note: 'Grup sudah tidak ada', decided_by: staff.name, decided_at: nowStr_()});\n      return r_renamesList_();\n    }\n    if (p.approve) {\n      if (groupNameTaken_(req.new_name, g.id)) throw appErr_('Nama \"' + req.new_name + '\" sudah dipakai grup lain. Tolak pengajuan ini.');\n      updateRow_('Groups', g._row, {name: req.new_name, rename_key: monthKey_(), rename_ts: String(Date.now())});\n\n      updateRow_('GroupRenames', req._row, {status: 'approved', note: note, decided_by: staff.name, decided_at: nowStr_()});\n    } else {\n      updateRow_('GroupRenames', req._row, {status: 'rejected', note: note, decided_by: staff.name, decided_at: nowStr_()});\n    }\n    notifyUsers_([req.requester_id], {kind: 'info', by: staff.name,\n      title: p.approve ? 'Nama grup disetujui' : 'Ganti nama grup ditolak',\n      body: p.approve ? 'Grupmu sekarang bernama \"' + req.new_name + '\".' : 'Pengajuan nama \"' + req.new_name + '\" ditolak admin.' + (note ? ' Alasan: ' + note : '')});\n    return r_renamesList_();\n  });\n}\n\n\n/* ───────── undangan ke nomor yang belum terdaftar ───────── */\nfunction autoUsername_(name) {\n  let base = String(name).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 16);\n  if (base.length < 3) base = (base + 'member').slice(0, 12);\n  for (let i = 0; i < 200; i++) {\n    const cand = i ? base.slice(0, 16) + (i + 1) : base, r = checkUsername_(cand);\n    if (r.ok && !usernameTaken_(r.key)) return r.name;\n  }\n  throw appErr_('Gagal membuat username otomatis. Coba nama lain.');\n}\n\n/* Cek apakah nomor terdaftar di WhatsApp (Fonnte /validate). Hasil di-cache; pengecekan ulang diberi jeda agar akun Fonnte tidak kena batas. */\nfunction waCheck_(phone, byUid, force) {\n  const cache = CacheService.getScriptCache(), ck = 'WAV_' + phone, hit = cache.get(ck);\n  if (hit && !force) {\n    if (hit === 'N') throw appErr_('Nomor ini tidak terdaftar di WhatsApp. Periksa lagi nomornya.', 'WA_INVALID');\n    return {verified: hit === 'Y'};\n  }\n  const token = prop_('FONNTE_TOKEN');\n  if (!token) { if (prop_('DEBUG_OTP') === 'true') return {verified: false}; throw appErr_('Pengecekan WhatsApp belum dikonfigurasi', 'WA_CHECK_FAIL'); }\n  const gap = cache.get('WAVGAP_' + byUid);\n  if (gap) throw appErr_('Tunggu ' + Math.max(1, Math.ceil((Number(gap) + 30000 - Date.now()) / 1000)) + ' detik sebelum mencoba lagi.', 'WA_WAIT');\n  rateLimit_('WAV_' + byUid, 12, 3600);\n  cache.put('WAVGAP_' + byUid, String(Date.now()), 30);\n  let ok = null;\n  try {\n    const res = UrlFetchApp.fetch('https://api.fonnte.com/validate', {method: 'post', headers: {Authorization: token}, payload: {target: phone, countryCode: '0'}, muteHttpExceptions: true});\n    const body = JSON.parse(res.getContentText());\n    if (res.getResponseCode() === 200 && body.status !== false) {\n      const reg = (body.registered || []).map(String), nreg = (body.not_registered || []).map(String);\n      if (reg.indexOf(phone) >= 0) ok = true; else if (nreg.indexOf(phone) >= 0) ok = false;\n    }\n  } catch (e) { ok = null; }\n  if (ok === null) throw appErr_('Gagal memeriksa nomor ke WhatsApp. Coba lagi sebentar lagi.', 'WA_CHECK_FAIL');\n  cache.put(ck, ok ? 'Y' : 'N', ok ? 86400 : 600);\n  if (!ok) throw appErr_('Nomor ini tidak terdaftar di WhatsApp. Periksa lagi nomornya.', 'WA_INVALID');\n  return {verified: true};\n}\n"}, {"name": "Aktivitas.gs", "code": "/*  Aktivitas.gs — Tahap 3: event & turnamen, badge, feed, koleksi game.  */\n\n// ───────── feed ─────────\nfunction feedAdd_(kind, username, text) {\n  if (!username) return;\n  appendObj_('Feed', {id: newId_('FED'), ts: nowStr_(), kind: kind, username: username, text: clean_(text, 140)});\n}\nfunction r_feed_() {\n  return {items: tail_('Feed', 20).reverse().map(function (f) { return {kind: f.kind, text: f.text, ts: f.ts}; })};\n}\n\n// ───────── badge ─────────\nfunction seedBadges_() {\n  if (readAll_('Badges').length) return;\n  [['pemain_baru', 'Pemain Baru', '🌱', 'Kunjungan pertama', 'visits', 1],\n   ['rutin', 'Rutin', '🔁', '10 kali berkunjung', 'visits', 10],\n   ['penjelajah_5', 'Penjelajah I', '🧭', 'Main 5 game berbeda', 'games', 5],\n   ['penjelajah_10', 'Penjelajah II', '🧭', 'Main 10 game berbeda', 'games', 10],\n   ['penjelajah_25', 'Penjelajah III', '🧭', 'Main 25 game berbeda', 'games', 25],\n   ['party_player', 'Party Player', '🎉', '5 kali main Party', 'party', 5],\n   ['juara', 'Juara Turnamen', '🏆', 'Masuk Top 3 turnamen', 'top3', 1],\n   ['naik_tier', 'Naik Tier', '⬆️', 'Naik ke tier di atas dasar', 'tier', 1]]\n    .forEach(function (b, i) { appendObj_('Badges', {id: newId_('BDG'), code: b[0], name: b[1], icon: b[2], description: b[3], metric: b[4], threshold: String(b[5]), active: 'Y', sort: String(i)}); });\n}\n\nfunction userMetrics_(u) {\n  const uid = u.user_id, m = {visits: 0, party: 0, games: 0, top3: 0, tier: 0};\n  findAll_('Visits', 'user_id', uid).forEach(function (v) { m.visits++; if (v.type === 'party') m.party++; });\n  const seen = {};\n  queryRows_('VisitGames', [['players', 'like', '*' + uid + '*']]).forEach(function (g) { if ((',' + g.players + ',').indexOf(',' + uid + ',') >= 0) seen[g.game_id] = 1; });\n  m.games = Object.keys(seen).length;\n  findAll_('ActReg', 'user_id', uid).forEach(function (r) { if (Number(r.placement) >= 1 && Number(r.placement) <= 3) m.top3++; });\n  const tiers = tiersActive_(), total = Number(u.vp_total) || 0;\n  tiers.forEach(function (t, i) { if (i > 0 && (Number(t.min_vp) || 0) <= total) m.tier = i; });\n  return m;\n}\n\n/* Cek & beri badge baru. Dipanggil di dalam lock. */\nfunction checkBadges_(u) {\n  if (!u || u.role !== 'customer' || !u.username) return [];\n  const have = {};\n  readAll_('UserBadges').forEach(function (b) { if (b.user_id === u.user_id) have[b.code] = 1; });\n  const defs = readAll_('Badges').filter(function (b) { return b.active !== 'N' && b.code && !have[b.code]; });\n  if (!defs.length) return [];\n  const m = userMetrics_(u), got = [];\n  defs.forEach(function (b) {\n    if ((m[b.metric] || 0) >= (Number(b.threshold) || 1)) {\n      appendObj_('UserBadges', {id: newId_('UBD'), user_id: u.user_id, code: b.code, ts: nowStr_()});\n      feedAdd_('badge', u.username, u.username + ' mendapat badge ' + b.name);\n      got.push(b.name);\n    }\n  });\n  return got;\n}\n\nfunction r_myBadges_(p, u) {\n  const have = {};\n  readAll_('UserBadges').forEach(function (b) { if (b.user_id === u.user_id) have[b.code] = b.ts; });\n  const m = userMetrics_(userById_(u.user_id));\n  return {badges: readAll_('Badges').filter(function (b) { return b.active !== 'N' && b.code; }).sort(function (a, b) { return Number(a.sort) - Number(b.sort); }).map(function (b) {\n    return {code: b.code, name: b.name, icon: b.icon, description: b.description, earned: !!have[b.code], ts: have[b.code] || '', progress: Math.min(m[b.metric] || 0, Number(b.threshold) || 1), target: Number(b.threshold) || 1};\n  })};\n}\n\nfunction r_badgesAdmin_() {\n  return {badges: readAll_('Badges').filter(function (b) { return b.code; }).map(function (b) { return {id: b.id, code: b.code, name: b.name, icon: b.icon, description: b.description, metric: b.metric, threshold: Number(b.threshold) || 1, active: b.active !== 'N'}; })};\n}\nfunction r_badgeSave_(p) {\n  return withLock_(function () {\n    const b = readAll_('Badges').filter(function (x) { return x.id === String(p.id); })[0];\n    if (!b) throw appErr_('Badge tidak ditemukan');\n    const name = clean_(p.name, 30), th = Math.round(Number(p.threshold));\n    if (!name) throw appErr_('Nama badge wajib diisi');\n    if (!(th >= 1 && th <= 100000)) throw appErr_('Target harus ≥ 1');\n    updateRow_('Badges', b._row, {name: name, icon: clean_(p.icon, 4) || b.icon, description: clean_(p.description, 80), threshold: String(th), active: p.active === false ? 'N' : 'Y'});\n    return r_badgesAdmin_();\n  });\n}\n\n// ───────── koleksi game ─────────\nfunction r_myCollection_(p, u) {\n  const cnt = {}, last = {}, games = {};\n  readAll_('Games').forEach(function (g) { games[g.id || ('R' + g._row)] = g; });\n  readAll_('VisitGames').forEach(function (v) {\n    if (v.players && (',' + v.players + ',').indexOf(',' + u.user_id + ',') >= 0) { cnt[v.game_id] = (cnt[v.game_id] || 0) + 1; last[v.game_id] = v.ts; }\n  });\n  const items = Object.keys(cnt).map(function (id) { const g = games[id]; return {id: id, name: g ? g.name : '(game dihapus)', image: g ? g.image_url : '', plays: cnt[id], last: last[id]}; })\n    .sort(function (a, b) { return String(b.last) < String(a.last) ? -1 : 1; });\n  return {items: items, total: items.length, catalog: Object.keys(games).filter(function (id) { return games[id].active !== 'N'; }).length};\n}\n\n// ───────── event & turnamen ─────────\nfunction actPub_(a, regs, me) {\n  const mine = me ? regs.filter(function (r) { return r.activity_id === a.id && r.user_id === me; })[0] : null;\n  return {id: a.id, kind: a.kind, title: a.title, description: a.description, start: a.start, vp: Number(a.vp) || 0, status: a.status, active: a.active !== 'N', gmId: a.gm_id,\n    registered: regs.filter(function (r) { return r.activity_id === a.id; }).length,\n    me: mine ? {status: mine.status, placement: Number(mine.placement) || 0} : null};\n}\n\nfunction r_actsList_(p, u) {\n  const regs = readAll_('ActReg');\n  return {items: readAll_('Activities').filter(function (a) { return a.title && a.active !== 'N'; })\n    .sort(function (a, b) { return String(b.start) < String(a.start) ? -1 : 1; }).slice(0, 30).map(function (a) { return actPub_(a, regs, u.user_id); })};\n}\n\nfunction r_actRegister_(p, u) {\n  return withLock_(function () {\n    const a = readAll_('Activities').filter(function (x) { return x.id === String(p.activityId); })[0];\n    if (!a || a.active === 'N') throw appErr_('Event tidak ditemukan');\n    if (a.status === 'closed') throw appErr_('Event ini sudah selesai');\n    const me = userById_(u.user_id), regs = readAll_('ActReg').filter(function (r) { return r.activity_id === a.id && r.user_id === me.user_id; });\n    if (p.cancel) {\n      if (!regs.length) return r_actsList_(p, u);\n      if (regs[0].status === 'attended') throw appErr_('Kehadiran sudah dicatat, tidak bisa dibatalkan');\n      updateRow_('ActReg', regs[0]._row, {status: 'cancelled'});\n      return r_actsList_(p, u);\n    }\n    if (regs.length && regs[0].status !== 'cancelled') throw appErr_('Kamu sudah terdaftar');\n    if (regs.length) updateRow_('ActReg', regs[0]._row, {status: 'registered'});\n    else appendObj_('ActReg', {id: newId_('REG'), activity_id: a.id, user_id: me.user_id, status: 'registered', ts: nowStr_()});\n    feedAdd_('join', me.username, me.username + ' bergabung di ' + (a.kind === 'tournament' ? 'turnamen ' : 'event ') + a.title);\n    return r_actsList_(p, u);\n  });\n}\n\nfunction r_actsAdmin_() {\n  const regs = readAll_('ActReg').filter(function (r) { return r.status !== 'cancelled'; }), um = usersMap_();\n  return {items: readAll_('Activities').filter(function (a) { return a.title; }).sort(function (a, b) { return String(b.start) < String(a.start) ? -1 : 1; }).map(function (a) {\n    const o = actPub_(a, regs, null); o.gm = (um[a.gm_id] || {}).username || ''; return o;\n  })};\n}\n\nfunction r_actSave_(p) {\n  const title = clean_(p.title, 80);\n  if (!title) throw appErr_('Judul wajib diisi');\n  const kind = p.kind === 'tournament' ? 'tournament' : 'event', vp = Math.round(Number(p.vp) || 0);\n  if (vp < 0 || vp > 100000) throw appErr_('VP tidak valid');\n  let gm = '';\n  if (p.gm) {\n    const g = findOne_('Users', 'username_key', String(p.gm).trim().replace(/^@/, '').toLowerCase());\n    if (!g || g.role !== 'gm') throw appErr_('Username GM tidak ditemukan (akun harus berperan GM)');\n    gm = g.user_id;\n  }\n  const obj = {kind: kind, title: title, description: clean_(p.description, 300), start: clean_(p.start, 20), vp: String(vp), gm_id: gm, status: p.status === 'closed' ? 'closed' : 'open', active: p.active === false ? 'N' : 'Y'};\n  return withLock_(function () {\n    if (p.id) {\n      const a = readAll_('Activities').filter(function (x) { return x.id === String(p.id); })[0];\n      if (!a) throw appErr_('Event tidak ditemukan');\n      updateRow_('Activities', a._row, obj);\n    } else { obj.id = newId_('ACT'); obj.created_at = nowStr_(); appendObj_('Activities', obj); }\n    return r_actsAdmin_();\n  });\n}\n\nfunction r_actDelete_(p) {\n  return withLock_(function () {\n    const a = readAll_('Activities').filter(function (x) { return x.id === String(p.id); })[0];\n    if (!a) throw appErr_('Event tidak ditemukan');\n    if (readAll_('ActReg').some(function (r) { return r.activity_id === a.id && r.status === 'attended'; })) throw appErr_('Sudah ada peserta yang hadir. Tutup saja (jangan hapus).');\n    delRow_('Activities', a._row);\n    return r_actsAdmin_();\n  });\n}\n\n/* Kasir/admin: semua event. GM: hanya event yang ia pegang. */\nfunction canRunAct_(staff, a) { return staff.role !== 'gm' || a.gm_id === staff.user_id; }\nfunction actFor_(id, staff) {\n  const a = readAll_('Activities').filter(function (x) { return x.id === String(id); })[0];\n  if (!a || a.active === 'N') throw appErr_('Event tidak ditemukan');\n  if (!canRunAct_(staff, a)) throw appErr_('Event ini bukan tanggung jawabmu', 'FORBIDDEN');\n  return a;\n}\n\nfunction r_actsMine_(p, staff) {\n  const regs = readAll_('ActReg');\n  return {items: readAll_('Activities').filter(function (a) { return a.title && a.active !== 'N' && a.status !== 'closed' && canRunAct_(staff, a); })\n    .map(function (a) { return actPub_(a, regs, null); })};\n}\n\nfunction r_actRoster_(p, staff) {\n  const a = actFor_(p.activityId, staff), um = usersMap_();\n  return {activity: {id: a.id, title: a.title, kind: a.kind, vp: Number(a.vp) || 0, status: a.status},\n    people: readAll_('ActReg').filter(function (r) { return r.activity_id === a.id && r.status !== 'cancelled'; }).map(function (r) {\n      const u = um[r.user_id] || {}; return {userId: r.user_id, username: u.username || '', status: r.status, placement: Number(r.placement) || 0};\n    })};\n}\n\nfunction r_actAttend_(p, staff) {\n  return withLock_(function () {\n    const a = actFor_(p.activityId, staff);\n    if (a.status === 'closed') throw appErr_('Event sudah ditutup');\n    const names = (Array.isArray(p.usernames) ? p.usernames : []).map(function (n) { return String(n || '').trim().replace(/^@/, '').toLowerCase(); }).filter(Boolean);\n    if (!names.length) throw appErr_('Pilih atau isi minimal satu username');\n    const out = [];\n    names.forEach(function (key) {\n      const u = findOne_('Users', 'username_key', key);\n      if (!u || u.role !== 'customer' || u.active === 'N') { out.push({username: key, ok: false, msg: 'tidak ditemukan'}); return; }\n      const reg = readAll_('ActReg').filter(function (r) { return r.activity_id === a.id && r.user_id === u.user_id; })[0];\n      if (reg && reg.status === 'attended') { out.push({username: u.username, ok: false, msg: 'sudah hadir'}); return; }\n      if (reg) updateRow_('ActReg', reg._row, {status: 'attended', ts: nowStr_()});\n      else appendObj_('ActReg', {id: newId_('REG'), activity_id: a.id, user_id: u.user_id, status: 'attended', ts: nowStr_()});\n      const vp = Number(a.vp) || 0;\n      if (vp > 0) awardVp_(u, vp, a.kind === 'tournament' ? 'tournament' : 'event', a.id, 'Hadir: ' + a.title, staff);\n      checkBadges_(userById_(u.user_id));\n      out.push({username: u.username, ok: true, vp: vp});\n    });\n    return {results: out};\n  });\n}\n\n/* Hasil turnamen: p.places = {1:'user', 2:'user', 3:'user'}; sekali saja, peserta harus sudah hadir. */\nfunction r_actResult_(p, staff) {\n  const s = settings_();\n  return withLock_(function () {\n    const a = actFor_(p.activityId, staff);\n    if (a.kind !== 'tournament') throw appErr_('Hanya untuk turnamen');\n    const regs = readAll_('ActReg').filter(function (r) { return r.activity_id === a.id; });\n    if (regs.some(function (r) { return Number(r.placement) > 0; })) throw appErr_('Hasil turnamen sudah dicatat');\n    const picks = [], seen = {};\n    [1, 2, 3].forEach(function (pl) {\n      const key = String((p.places || {})[pl] || '').trim().replace(/^@/, '').toLowerCase();\n      if (!key) return;\n      const u = findOne_('Users', 'username_key', key);\n      const reg = u ? regs.filter(function (r) { return r.user_id === u.user_id && r.status === 'attended'; })[0] : null;\n      if (!reg) throw appErr_('Juara ' + pl + ' (' + key + ') belum tercatat hadir');\n      if (seen[u.user_id]) throw appErr_('Satu orang tidak bisa di dua peringkat');\n      seen[u.user_id] = 1; picks.push({pl: pl, u: u, reg: reg});\n    });\n    if (!picks.length) throw appErr_('Isi minimal Juara 1');\n    picks.forEach(function (x) {\n      updateRow_('ActReg', x.reg._row, {placement: String(x.pl)});\n      const vp = Number(s['vp_top' + x.pl]) || 0;\n      if (vp > 0) awardVp_(x.u, vp, 'tournament', a.id, 'Juara ' + x.pl + ': ' + a.title, staff);\n      feedAdd_('win', x.u.username, x.u.username + ' juara ' + x.pl + ' di ' + a.title);\n      checkBadges_(userById_(x.u.user_id));\n    });\n    updateRow_('Activities', a._row, {status: 'closed'});\n    return {ok: true};\n  });\n}\n"}, {"name": "Notif.gs", "code": "/*  Notif.gs — Kotak notifikasi, pengumuman admin, dan pengingat otomatis.  */\n\n// ───────── dasar ─────────\nfunction cacheEachChunk_(keys, fn) { for (let i = 0; i < keys.length; i += 100) fn(keys.slice(i, i + 100)); }\n\nfunction unreadCount_(uid) {\n  const c = CacheService.getScriptCache(), hit = c.get('NU_' + uid);\n  if (hit !== null && hit !== undefined) return Number(hit) || 0;\n  const n = dbSelect_('notifications', {filters: [['user_id', 'eq', uid], ['read', 'neq', 'Y']], select: 'rn', limit: 1000}).length;\n  c.put('NU_' + uid, String(n), 21600);\n  return n;\n}\n\n/* Kirim notifikasi ke banyak pengguna sekaligus. Dipanggil di dalam lock. */\nfunction notifyUsers_(uids, n) {\n  uids = uids.filter(function (x, i) { return x && uids.indexOf(x) === i; });\n  if (!uids.length) return 0;\n  const ts = nowStr_(), nids = newIds_('NTF', uids.length);\n  appendMany_('Notifications', uids.map(function (uid, i) {\n    return {id: nids[i], user_id: uid, kind: n.kind || 'info', title: clean_(n.title, 60), body: clean_(n.body, 300), ts: ts, read: 'N', ref: n.ref || '', by_name: n.by || ''};\n  }));\n  const c = CacheService.getScriptCache();\n  cacheEachChunk_(uids, function (part) {\n    c.removeAll(part.map(function (u) { return 'NU_' + u; }));\n    __DB.pingMany(JSON.stringify(part.map(function (u) { return [pingTopic_(u), String(Date.now())]; })));\n  });\n  try {   // push ke HP: kegagalan tidak boleh menggagalkan notifikasi di app\n    const set = {}; uids.forEach(function (u) { set[u] = 1; });\n    const subs = readAll_('PushSubs').filter(function (x) { return set[x.user_id]; });\n    if (subs.length) pushSend_(subs, {title: clean_(n.title, 60), body: clean_(n.body, 300), tag: n.ref || 'n'});\n  } catch (e) { /* abaikan */ }\n  return uids.length;\n}\n\n// ───────── rute pelanggan ─────────\nfunction r_notifList_(p, u) {\n  const items = tail_('Notifications', 4000).filter(function (r) { return r.user_id === u.user_id; }).reverse().slice(0, 40)\n    .map(function (r) { return {id: r.id, kind: r.kind, title: r.title, body: r.body, ts: r.ts, read: r.read === 'Y'}; });\n  return {items: items, unread: unreadCount_(u.user_id)};\n}\n\nfunction r_notifRead_(p, u) {\n  return withLock_(function () {\n    const ids = Array.isArray(p.ids) ? p.ids.map(String) : null;\n    tail_('Notifications', 4000).forEach(function (r) {\n      if (r.user_id === u.user_id && r.read !== 'Y' && (!ids || ids.indexOf(r.id) >= 0)) updateRow_('Notifications', r._row, {read: 'Y'});\n    });\n    CacheService.getScriptCache().remove('NU_' + u.user_id);\n    return r_notifList_(p, u);\n  });\n}\n\n// ───────── pengumuman admin ─────────\nfunction notifRecipients_(t) {\n  t = t || {};\n  const customers = readAll_('Users').filter(function (u) { return u.role === 'customer' && u.active !== 'N'; });\n  if (t.type === 'all') return customers.map(function (u) { return u.user_id; });\n  if (t.type === 'tier') {\n    const name = String(t.tier || '').trim().toLowerCase();\n    if (!name) throw appErr_('Pilih tier');\n    return customers.filter(function (u) { const tr = vpView_(u).tier; return tr && tr.name.toLowerCase() === name; }).map(function (u) { return u.user_id; });\n  }\n  if (t.type === 'group') {\n    const g = groupById_(String(t.groupId || ''));\n    if (!g || g.status === 'dissolved') throw appErr_('Grup tidak ditemukan');\n    return gmActive_(g.id).filter(function (m) { return m.user_id; }).map(function (m) { return m.user_id; });\n  }\n  if (t.type === 'user') {\n    const u = findCustomerByHandle_(t.username);\n    if (!u) throw appErr_('Pelanggan tidak ditemukan. Cek username atau nomor WhatsApp-nya.');\n    return [u.user_id];\n  }\n  throw appErr_('Pilih tujuan notifikasi');\n}\n\nfunction r_notifSend_(p, staff) {\n  const title = clean_(p.title, 60), body = clean_(p.body, 300);\n  if (!title) throw appErr_('Judul wajib diisi');\n  if (!body) throw appErr_('Isi pesan wajib diisi');\n  const kind = ['info', 'reminder', 'event', 'reward'].indexOf(p.kind) >= 0 ? p.kind : 'info';\n  return withLock_(function () {\n    const ids = notifRecipients_(p.target);\n    if (!ids.length) throw appErr_('Tidak ada penerima untuk tujuan ini');\n    if (ids.length > 3000) throw appErr_('Terlalu banyak penerima (maks 3000)');\n    return {sent: notifyUsers_(ids, {kind: kind, title: title, body: body, by: staff.name})};\n  });\n}\n\n// ───────── pengingat otomatis (diatur admin) ─────────\nconst NOTIF_RULES_ = [\n  {code: 'inactive', name: 'Lama tidak berkunjung', days: 30, daysLabel: 'Hari tanpa kunjungan', kind: 'reminder',\n   title: 'Kangen main nih 🎲', body: 'Hai {username}, sudah {hari} hari kamu belum mampir. Yuk main lagi!'},\n  {code: 'event_reminder', name: 'Pengingat event', days: 1, daysLabel: 'Berapa hari sebelum acara', kind: 'event',\n   title: 'Segera: {event}', body: '{event} dimulai {waktu}. Sampai ketemu!'},\n  {code: 'reward_ready', name: 'Reward siap ditukar', days: 0, daysLabel: '', kind: 'reward',\n   title: 'Reward siap ditukar 🎁', body: 'Kartu stamp kamu sudah bisa ditukar: {reward}. Tunjukkan QR ke kasir.'},\n  {code: 'party_expiring', name: 'Grup Party hampir bubar', days: 7, daysLabel: 'Sisa hari sebelum bubar', kind: 'reminder',\n   title: 'Grup {grup} butuh anggota', body: 'Sisa {hari} hari sebelum grup dibubarkan. Undang teman agar diskon Party aktif lagi.'},\n  {code: 'stamp_near', name: 'Stamp hampir penuh', days: 1, daysLabel: 'Sisa stamp yang memicu pengingat', kind: 'reward',\n   title: 'Tinggal {sisa} stamp lagi! ✨', body: 'Kartu {event}: {sisa} stamp lagi untuk {reward}. Yuk mampir!'}\n];\n\nfunction seedNotifRules_() {\n  const have = {};\n  readAll_('NotifRules').forEach(function (r) { have[r.code] = 1; });\n  NOTIF_RULES_.forEach(function (d, i) {\n    if (!have[d.code]) appendObj_('NotifRules', {id: newId_('NRL'), code: d.code, name: d.name, enabled: 'Y', days: String(d.days), title: d.title, body: d.body, last_run: ''});\n  });\n}\n\nconst render_ = function (tpl, vars) { return String(tpl).replace(/\\{(\\w+)\\}/g, function (m, k) { return vars[k] !== undefined ? vars[k] : m; }); };\nfunction rulePub_(r) {\n  const d = NOTIF_RULES_.filter(function (x) { return x.code === r.code; })[0] || {};\n  return {id: r.id, code: r.code, name: r.name, enabled: r.enabled !== 'N', days: Number(r.days) || 0, daysLabel: d.daysLabel || '', title: r.title, body: r.body, lastRun: r.last_run || ''};\n}\nfunction ruleByCode_(code) { return readAll_('NotifRules').filter(function (r) { return r.code === code && r.enabled !== 'N'; })[0] || null; }\nfunction sentRefs_(prefix) {\n  const set = {};\n  tail_('Notifications', 4000).forEach(function (r) { if (r.ref && r.ref.indexOf(prefix) === 0) set[r.user_id + '|' + r.ref] = r.ts; });\n  return set;\n}\nconst tsAgo_ = function (days) { return fmt_(new Date(Date.now() - days * 86400000), 'yyyy-MM-dd HH:mm:ss'); };\n\nfunction r_notifRules_() { return {rules: readAll_('NotifRules').filter(function (r) { return r.code; }).map(rulePub_)}; }\nfunction r_notifRuleSave_(p) {\n  return withLock_(function () {\n    const r = readAll_('NotifRules').filter(function (x) { return x.id === String(p.id); })[0];\n    if (!r) throw appErr_('Aturan tidak ditemukan');\n    const title = clean_(p.title, 60), body = clean_(p.body, 300), days = Math.round(Number(p.days));\n    if (!title || !body) throw appErr_('Judul dan isi wajib diisi');\n    if (!(days >= 0 && days <= 365)) throw appErr_('Hari harus 0–365');\n    updateRow_('NotifRules', r._row, {enabled: p.enabled === false ? 'N' : 'Y', days: String(days), title: title, body: body});\n    return r_notifRules_();\n  });\n}\nfunction r_notifRunAuto_() { return {sent: runAutoNotifs()}; }\n\n/* Dijalankan harian oleh trigger (jam 09.00) atau manual oleh admin. Aman diulang: tiap pengingat dicatat agar tidak dobel. */\nfunction runAutoNotifs() {\n  return withLock_(function () {\n    const out = {inactive: 0, event_reminder: 0, party_expiring: 0};\n    const um = usersMap_();\n    // 1) lama tidak berkunjung\n    let r = ruleByCode_('inactive');\n    if (r) {\n      const days = Number(r.days) || 30, cutoff = tsAgo_(days), last = {};\n      dbSelect_('visits', {select: 'user_id,ts', all: true}).forEach(function (v) { if (v.user_id && String(v.ts) > (last[v.user_id] || '')) last[v.user_id] = v.ts; });\n      const sent = sentRefs_('auto:inactive');\n      const ids = [];\n      Object.keys(um).forEach(function (id) {\n        const u = um[id];\n        if (u.role !== 'customer' || u.active === 'N' || !u.username) return;\n        const la = last[id] || String(u.created_at || '');\n        if (!la || la > cutoff) return;\n        const prev = sent[id + '|auto:inactive'];\n        if (prev && prev > cutoff) return;\n        ids.push(id);\n      });\n      ids.forEach(function (id) {\n        const u = um[id], laStr = last[id] || u.created_at, hari = Math.max(days, Math.floor((Date.now() - new Date(String(laStr).replace(' ', 'T')).getTime()) / 86400000) || days);\n        notifyUsers_([id], {kind: 'reminder', ref: 'auto:inactive', title: render_(r.title, {username: u.username, hari: hari}), body: render_(r.body, {username: u.username, hari: hari})});\n      });\n      out.inactive = ids.length;\n    }\n    // 2) pengingat event\n    r = ruleByCode_('event_reminder');\n    if (r) {\n      const nowN = fmt_(new Date(), 'yyyy-MM-dd HH:mm'), futN = fmt_(new Date(Date.now() + (Number(r.days) || 1) * 86400000), 'yyyy-MM-dd HH:mm');\n      readAll_('Activities').forEach(function (a) {\n        if (a.active === 'N' || a.status === 'closed' || !a.title) return;\n        const st = String(a.start || '').replace('T', ' ').slice(0, 16);\n        if (!/^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}$/.test(st) || st <= nowN || st > futN) return;\n        const ref = 'auto:event:' + a.id, sent = sentRefs_(ref);\n        const ids = readAll_('ActReg').filter(function (x) { return x.activity_id === a.id && x.status === 'registered' && !sent[x.user_id + '|' + ref]; }).map(function (x) { return x.user_id; });\n        const vars = {event: a.title, waktu: a.start};\n        out.event_reminder += notifyUsers_(ids, {kind: 'event', ref: ref, title: render_(r.title, vars), body: render_(r.body, vars)});\n      });\n    }\n    // 3) grup Party hampir bubar\n    r = ruleByCode_('party_expiring');\n    if (r) {\n      readAll_('Groups').forEach(function (g) {\n        if (g.status !== 'waiting' || !g.waiting_since) return;\n        const left = Math.ceil(((Number(g.waiting_since) || 0) + WAIT_MS - Date.now()) / 86400000);\n        if (left > (Number(r.days) || 7) || left < 0) return;\n        const ref = 'auto:party:' + g.id, sent = sentRefs_(ref);\n        if (sent[g.leader_id + '|' + ref]) return;\n        const vars = {grup: g.name, hari: left};\n        out.party_expiring += notifyUsers_([g.leader_id], {kind: 'reminder', ref: ref, title: render_(r.title, vars), body: render_(r.body, vars)});\n      });\n    }\n    return out;\n  });\n}\n\n/* Dipanggil setelah stamp bertambah (dalam lock): ingatkan bila kartu tinggal N stamp lagi menuju reward berikutnya. */\nfunction notifyNearIfReady_(cust, u) {\n  const r = ruleByCode_('stamp_near');\n  if (!r || !cust) return;\n  const want = Math.max(1, Number(r.days) || 1), sent = sentRefs_('auto:near:');\n  (cust.campaigns || []).forEach(function (c) {\n    c.cards.forEach(function (k) {\n      const nx = k.next;\n      if (!nx || nx.remaining !== want) return;\n      const ref = 'auto:near:' + k.id + ':' + nx.id;\n      if (sent[u.user_id + '|' + ref]) return;\n      const vars = {sisa: nx.remaining, event: c.name || '', reward: nx.name};\n      notifyUsers_([u.user_id], {kind: 'reward', ref: ref, title: render_(r.title, vars), body: render_(r.body, vars)});\n    });\n  });\n}\n\n/* Dipanggil setelah stamp bertambah (dalam lock): beri tahu bila ada reward yang baru bisa ditukar. */\nfunction notifyRewardIfReady_(cust, u) {\n  const r = ruleByCode_('reward_ready');\n  if (!r || !cust) return;\n  const names = [], refs = [];\n  (cust.campaigns || []).forEach(function (c) { c.cards.forEach(function (k) { k.milestones.forEach(function (m) { if (m.status === 'available') { names.push(m.name); refs.push('auto:reward:' + k.id + ':' + m.id); } }); }); });\n  if (!names.length) return;\n  const sent = sentRefs_('auto:reward:'), fresh = [];\n  refs.forEach(function (ref, i) { if (!sent[u.user_id + '|' + ref]) fresh.push({ref: ref, name: names[i]}); });\n  fresh.forEach(function (f) {\n    notifyUsers_([u.user_id], {kind: 'reward', ref: f.ref, title: render_(r.title, {reward: f.name}), body: render_(r.body, {reward: f.name})});\n  });\n}\n\n\n// ───────── Web Push (dikirim lewat fungsi Netlify) ─────────\nconst pushProp_ = function (k) { return PropertiesService.getScriptProperties().getProperty(k) || ''; };\n\nfunction r_pushKey_() { return {key: pushProp_('VAPID_PUBLIC'), enabled: !!(pushProp_('VAPID_PUBLIC') && pushProp_('PUSH_URL') && pushProp_('PUSH_SECRET'))}; }\n\nfunction r_pushSubscribe_(p, u) {\n  const ep = String(p.endpoint || ''), k = p.keys || {};\n  if (!/^https:\\/\\/[^\\s]{10,500}$/.test(ep) || !k.p256dh || !k.auth || String(k.p256dh).length > 120 || String(k.auth).length > 40) throw appErr_('Data langganan tidak valid');\n  return withLock_(function () {\n    const mine = readAll_('PushSubs').filter(function (x) { return x.user_id === u.user_id; });\n    const same = readAll_('PushSubs').filter(function (x) { return x.endpoint === ep; })[0];\n    const row = {user_id: u.user_id, endpoint: ep, p256dh: String(k.p256dh), auth: String(k.auth), ts: nowStr_(), ua: clean_(p.ua, 80)};\n    if (same) updateRow_('PushSubs', same._row, row);\n    else {\n      if (mine.length >= 5) deleteWhere_('PushSubs', 'id', mine[0].id);   // maks 5 perangkat, buang yang terlama\n      row.id = newId_('PSH'); appendObj_('PushSubs', row);\n    }\n    return {ok: true};\n  });\n}\n\nfunction r_pushUnsubscribe_(p, u) {\n  return withLock_(function () {\n    const ep = String(p.endpoint || '');\n    readAll_('PushSubs').filter(function (x) { return x.endpoint === ep && x.user_id === u.user_id; }).forEach(function () { deleteWhere_('PushSubs', 'endpoint', ep); });\n    return {ok: true};\n  });\n}\n\nfunction pushSend_(subs, payload) {\n  const url = pushProp_('PUSH_URL'), secret = pushProp_('PUSH_SECRET');\n  if (!url || !secret || !subs.length || typeof UrlFetchApp === 'undefined') return {sent: 0, gone: 0, error: ''};\n  const reqs = [];\n  for (let i = 0; i < subs.length; i += 80) {\n    reqs.push({url: url, method: 'post', contentType: 'application/json', headers: {'X-Push-Secret': secret}, muteHttpExceptions: true,\n      payload: JSON.stringify({subs: subs.slice(i, i + 80).map(function (s) { return {endpoint: s.endpoint, keys: {p256dh: s.p256dh, auth: s.auth}}; }), payload: Object.assign({url: '/'}, payload)})});\n  }\n  let sent = 0, gone = 0, error = '';\n  UrlFetchApp.fetchAll(reqs).forEach(function (res) {\n    let body = null;\n    try { body = JSON.parse(res.getContentText()); } catch (e) { /* bukan JSON */ }\n    if (!body || !body.ok) { error = (body && body.error) || ('HTTP ' + res.getResponseCode()); return; }\n    body.results.forEach(function (r) {\n      if (r.status >= 200 && r.status < 300) sent++;\n      else if (r.status === 404 || r.status === 410) { gone++; deleteWhere_('PushSubs', 'endpoint', r.endpoint); }\n      else if (!error) error = 'push service membalas ' + (r.status || r.error || '?');\n    });\n  });\n  return {sent: sent, gone: gone, error: error};\n}\n\nfunction r_pushConfigGet_() {\n  return {url: pushProp_('PUSH_URL'), publicKey: pushProp_('VAPID_PUBLIC'), hasSecret: !!pushProp_('PUSH_SECRET'), subscribers: readAll_('PushSubs').length};\n}\n\nfunction r_pushConfigSave_(p) {\n  const url = String(p.url || '').trim(), pub = String(p.publicKey || '').trim(), sec = String(p.secret || '').trim();\n  if (url && !/^https:\\/\\/[^\\s]+\\/\\.netlify\\/functions\\/push$/.test(url)) throw appErr_('Alamat harus berbentuk https://NAMA-SITUS.netlify.app/.netlify/functions/push');\n  if (pub && !/^[A-Za-z0-9_-]{80,100}$/.test(pub)) throw appErr_('Kunci publik VAPID tidak valid (salin utuh dari keygen.html)');\n  const props = PropertiesService.getScriptProperties();\n  props.setProperty('PUSH_URL', url); props.setProperty('VAPID_PUBLIC', pub);\n  if (sec) { if (sec.length < 16) throw appErr_('Secret minimal 16 karakter'); props.setProperty('PUSH_SECRET', sec); }\n  return r_pushConfigGet_();\n}\n\n/* Kirim push uji ke perangkat milik admin yang sedang login dan tampilkan hasil mentahnya. */\nfunction r_pushTest_(p, staff) {\n  const subs = readAll_('PushSubs').filter(function (x) { return x.user_id === staff.user_id; });\n  if (!subs.length) throw appErr_('Perangkat ini belum berlangganan. Tekan \"Aktifkan push di perangkat ini\" dulu.');\n  const r = pushSend_(subs, {title: 'Tes notifikasi', body: 'Kalau ini muncul, push sudah berfungsi 🎉', tag: 'test'});\n  return r;\n}\n"}, {"name": "Admin.gs", "code": "/*  Admin.gs — ekspor CSV, log aktivitas admin, pembatalan input, pencarian cepat, cadangan.  */\n\nconst EXPORTABLE_ = {\n  Users: ['user_id','username','name','phone','gender','role','member_code','vp_total','total_earned','total_redeemed','active','created_at','last_login'],\n  Visits: null, VisitGames: null, Stamps: null, Redemptions: null, PointsLedger: null, Groups: null, GroupMembers: null, Activities: null, ActReg: null, AdminLog: null\n};\nconst BACKUP_TABLES_ = ['Users','Cards','Stamps','Redemptions','PointsLedger','Visits','VisitGames','Groups','GroupMembers','Kids','GroupRenames','Campaigns','Rewards','Events','Games','Tiers','Activities','ActReg','Badges','UserBadges','AdminLog','Settings'];\n\nfunction csvCell_(v) {\n  let s = String(v == null ? '' : v);\n  if (/^[=+\\-@\\t\\r]/.test(s)) s = \"'\" + s;   // cegah rumus terbaca di Excel\n  return /[\",\\n\\r]/.test(s) ? '\"' + s.replace(/\"/g, '\"\"') + '\"' : s;\n}\nfunction csvOf_(name, cols) {\n  cols = cols || HEADERS[name];\n  const lines = [cols.join(',')];\n  queryRows_(name, []).forEach(function (r) { lines.push(cols.map(function (c) { return csvCell_(r[c]); }).join(',')); });\n  return {csv: lines.join('\\n'), n: lines.length - 1};\n}\n\nfunction r_exportCsv_(p) {\n  const name = String(p.table || '');\n  if (!EXPORTABLE_.hasOwnProperty(name) || !HEADERS[name]) throw appErr_('Tabel tidak bisa diekspor');\n  const r = csvOf_(name, EXPORTABLE_[name]);\n  return {filename: 'aiueo-' + name.toLowerCase() + '-' + fmt_(new Date(), 'yyyyMMdd') + '.csv', csv: '﻿' + r.csv, rows: r.n};\n}\nfunction r_exportTables_() { return {tables: Object.keys(EXPORTABLE_)}; }\n\nfunction r_adminLog_() {\n  return {items: tail_('AdminLog', 150).reverse().map(function (r) { return {id: r.id, ts: r.ts, by: r.by_name, action: r.action, detail: r.detail}; })};\n}\n\n/* Batalkan satu input stamp (earn) atau VP. Tercatat sebagai baris baru, data lama tidak dihapus. */\nfunction r_entryVoid_(p, admin) {\n  const reason = clean_(p.reason, 100);\n  if (!reason) throw appErr_('Alasan pembatalan wajib diisi');\n  return withLock_(function () {\n    if (p.kind === 'stamp') {\n      const row = findOne_('Stamps', 'id', String(p.id));\n      if (!row || row.type !== 'earn') throw appErr_('Input stamp tidak ditemukan');\n      if (findOne_('Stamps', 'void_of', row.id)) throw appErr_('Input ini sudah dibatalkan');\n      const qty = Number(row.qty) || 0, u = userById_(row.user_id), card = findOne_('Cards', 'card_id', row.card_id);\n      if (!u || !card) throw appErr_('Kartu tidak ditemukan');\n      if (card.status !== 'active') throw appErr_('Kartu sudah selesai. Koreksi manual lewat \"Koreksi stamp\".');\n      const cur = Number(card.stamps) || 0;\n      if (cur < qty) throw appErr_('Stamp di kartu kurang dari jumlah yang dibatalkan. Koreksi manual.');\n      const claimedMax = splitIds_(card.claimed_ids).length ? 1 : 0;\n      if (claimedMax) throw appErr_('Reward di kartu ini sudah ditukar. Koreksi manual lewat \"Koreksi stamp\".');\n      updateRow_('Cards', card._row, {stamps: cur - qty});\n      updateRow_('Users', u._row, {total_earned: Math.max(0, (Number(u.total_earned) || 0) - qty)});\n      appendObj_('Stamps', {id: newId_('STP'), user_id: u.user_id, customer_name: u.name, qty: -qty, type: 'void', by_user: admin.user_id, by_name: admin.name,\n        note: 'Batal: ' + reason, ts: nowStr_(), stamp_type: row.stamp_type, card_id: row.card_id, void_of: row.id});\n      touch_(u.user_id);\n      return {ok: true};\n    }\n    if (p.kind === 'vp') {\n      const row = findOne_('PointsLedger', 'id', String(p.id));\n      if (!row || row.source === 'void') throw appErr_('Input VP tidak ditemukan');\n      if (queryRows_('PointsLedger', [['ref', 'eq', row.id], ['source', 'eq', 'void']]).length) throw appErr_('Input ini sudah dibatalkan');\n      const u = userById_(row.user_id), amt = Number(row.amount) || 0;\n      if (!u || !amt) throw appErr_('Data VP tidak valid');\n      awardVp_(u, -amt, 'void', row.id, 'Batal: ' + reason, admin);\n      return {ok: true};\n    }\n    throw appErr_('Jenis tidak dikenal');\n  });\n}\n\n/* Saran pelanggan saat kasir mengetik (nama / username / 4 digit akhir nomor). */\nfunction r_custSuggest_(p) {\n  const q = String(p.q || '').trim().toLowerCase().replace(/^@/, '');\n  if (q.length < 2) return {users: []};\n  const digits = q.replace(/\\D/g, ''), out = [];\n  readAll_('Users').forEach(function (u) {\n    if (out.length >= 8 || u.role !== 'customer' || u.active === 'N') return;\n    const hit = String(u.name).toLowerCase().indexOf(q) >= 0 || String(u.username_key || '').indexOf(q) >= 0 ||\n      (digits.length >= 3 && String(u.phone).slice(-Math.max(4, digits.length)).indexOf(digits) >= 0 && String(u.phone).indexOf(digits) >= 0);\n    if (hit) out.push({id: u.user_id, name: u.name, username: u.username || '', phone4: String(u.phone).slice(-4), code: u.member_code});\n  });\n  return {users: out};\n}\n\n/* ───────── cadangan ───────── */\nfunction makeBackup_() {\n  const ts = nowStr_(), stamp = fmt_(new Date(), 'yyyy-MM-dd');\n  BACKUP_TABLES_.forEach(function (t) {\n    const r = csvOf_(t);\n    appendObj_('Backups', {id: newId_('BKP'), ts: ts, table_name: t, n_rows: r.n, csv: r.csv});\n  });\n  // simpan 4 cadangan terakhir (per tanggal)\n  const dates = {};\n  dbSelect_('backups', {select: 'ts', all: true}).forEach(function (b) { dates[String(b.ts).slice(0, 10)] = 1; });\n  const keep = Object.keys(dates).sort().slice(-4), drop = Object.keys(dates).filter(function (d) { return keep.indexOf(d) < 0; });\n  drop.forEach(function (d) { __DB.remove('backups', JSON.stringify([['ts', 'like', d + '*']])); });\n  invalidate_('Backups');\n  return {date: stamp, tables: BACKUP_TABLES_.length};\n}\nfunction r_backupMake_() { return withLock_(function () { makeBackup_(); return r_backupsList_(); }); }\nfunction r_backupsList_() {\n  const rows = dbSelect_('backups', {select: 'id,ts,table_name,n_rows', order: 'rn.desc', limit: 200});\n  const by = {};\n  rows.forEach(function (r) { const d = String(r.ts).slice(0, 10); (by[d] = by[d] || []).push({id: r.id, table: r.table_name, rows: Number(r.n_rows) || 0}); });\n  return {backups: Object.keys(by).sort().reverse().map(function (d) { return {date: d, items: by[d]}; })};\n}\nfunction r_backupGet_(p) {\n  const r = findOne_('Backups', 'id', String(p.id));\n  if (!r) throw appErr_('Cadangan tidak ditemukan');\n  return {filename: 'cadangan-' + String(r.ts).slice(0, 10) + '-' + r.table_name.toLowerCase() + '.csv', csv: '﻿' + r.csv};\n}\n"}];
